    view = discord.ui.View(timeout=None)
    for status in ("win", "loss", "push"):
        view.add_item(SettleButton(pick_id, status))
    view.add_item(FollowButton(pick_id, "tail"))
    view.add_item(FollowButton(pick_id, "fade"))
