ESPN_STANDINGS = "https://site.api.espn.com/apis/v2/sports/{path}/standings"
ESPN_RANKINGS = "https://site.api.espn.com/apis/site/v2/sports/{path}/rankings"
ESPN_BOARD = "https://site.api.espn.com/apis/site/v2/sports/{path}/scoreboard"
GEOCODE = "https://geocoding-api.open-meteo.com/v1/search"
FORECAST = "https://api.open-meteo.com/v1/forecast"
LIQUIPEDIA = "https://liquipedia.net/counterstrike/api.php"
_misc_cache: dict[str, tuple[float, object]] = {}
SPORT_LEAGUES = [app_commands.Choice(name=n, value=p) for p, n in LEAGUE_NAMES.items()][:25]


async def cached_json(url: str, params: dict, ttl: int) -> dict:
    key = url + "?" + "&".join(f"{k}={v}" for k, v in sorted(params.items()))
    hit = _misc_cache.get(key)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    data = await _get_json(url, params)
    _misc_cache[key] = (time.monotonic() + ttl, data)
    return data


async def next_game(team_text: str, paths: list[str]) -> Optional[tuple[str, dict, int]]:
    """(league path, event, team index) for this team's next (or current) game within a week."""
    now = datetime.now(timezone.utc)
    for path in paths:
        games = await find_games(team_text, [path], now - timedelta(days=1))
        upcoming = [(ev, i) for ev, i in games if not ev["final"]]
        if upcoming:
            ev, i = upcoming[0]
            return path, ev, i
        later = []
        for offset in range(4, 8):
            for ev in await fetch_scoreboard(path, (now + timedelta(days=offset)).astimezone(TZ)):
                for i, t in enumerate(ev["teams"]):
                    if team_matches(team_text, t) and not ev["final"]:
                        later.append((ev, i))
        if later:
            ev, i = sorted(later, key=lambda x: x[0]["date"])[0]
            return path, ev, i
    return None


# ---- weather -----------------------------------------------------------------------------------

async def kickoff_weather(city: str, state: str, when: datetime) -> Optional[dict]:
    try:
        geo = await cached_json(GEOCODE, {"name": city, "count": 5, "country_code": "US" if state else ""}, 86400 * 7)
        results = geo.get("results") or []
        if state:
            results = [r for r in results if (r.get("admin1") or "").lower().startswith(US_STATES.get(state, state).lower()[:4])] or results
        if not results:
            return None
        lat, lon = results[0]["latitude"], results[0]["longitude"]
        day = when.astimezone(timezone.utc).date().isoformat()
        fc = await cached_json(FORECAST, {"latitude": lat, "longitude": lon, "timezone": "UTC", "start_date": day,
                                          "end_date": day, "temperature_unit": "fahrenheit", "wind_speed_unit": "mph",
                                          "hourly": "temperature_2m,precipitation_probability,wind_speed_10m,wind_gusts_10m"},
                               3600)
        hourly = fc.get("hourly") or {}
        times = hourly.get("time") or []
        target = when.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:00")
        if target not in times:
            return None
        k = times.index(target)
        def at(name):
            vals = hourly.get(name) or []
            return vals[k] if k < len(vals) else None
        return {"temp": at("temperature_2m"), "rain": at("precipitation_probability"), "wind": at("wind_speed_10m"),
                "gust": at("wind_gusts_10m")}
    except Exception:
        log.warning("Weather lookup failed for %s", city)
        return None


US_STATES = {"AL": "Alabama", "AZ": "Arizona", "AR": "Arkansas", "CA": "California", "CO": "Colorado", "CT": "Connecticut",
             "DC": "District of Columbia", "FL": "Florida", "GA": "Georgia", "IL": "Illinois", "IN": "Indiana", "IA": "Iowa",
             "KS": "Kansas", "KY": "Kentucky", "LA": "Louisiana", "MD": "Maryland", "MA": "Massachusetts", "MI": "Michigan",
             "MN": "Minnesota", "MS": "Mississippi", "MO": "Missouri", "NE": "Nebraska", "NV": "Nevada", "NJ": "New Jersey",
             "NY": "New York", "NC": "North Carolina", "OH": "Ohio", "OK": "Oklahoma", "OR": "Oregon", "PA": "Pennsylvania",
             "SC": "South Carolina", "TN": "Tennessee", "TX": "Texas", "UT": "Utah", "VA": "Virginia", "WA": "Washington",
             "WI": "Wisconsin", "WV": "West Virginia", "ID": "Idaho", "NM": "New Mexico", "AK": "Alaska", "HI": "Hawaii"}


def weather_line(w: dict) -> str:
    bits = []
    if w.get("temp") is not None:
        bits.append(f"{w['temp']:.0f}°F")
    if w.get("wind") is not None:
        bits.append(f"wind {w['wind']:.0f} mph" + (f" (gusts {w['gust']:.0f})" if w.get("gust") and w["gust"] >= w["wind"] + 8 else ""))
    if w.get("rain") is not None:
        bits.append(f"{w['rain']:.0f}% chance of rain")
    flag = ""
    if (w.get("wind") or 0) >= 15 or (w.get("gust") or 0) >= 25:
        flag = " · 🌬️ windy, can hurt passing and kicking"
    elif (w.get("rain") or 0) >= 60:
        flag = " · 🌧️ likely wet"
    elif w.get("temp") is not None and w["temp"] <= 25:
        flag = " · 🥶 cold"
    return ", ".join(bits) + flag


def _place_close(query: str, result: dict) -> bool:
    words = [w for w in re.findall(r"[a-z0-9]+", (query or "").lower()) if len(w) >= 2]
    blob = f"{result.get('name') or ''} {result.get('admin1') or ''}".lower()
    return bool(words) and any(w in blob for w in words)


def _hour_label(stamp: str) -> str:
    hour = int(stamp[11:13])
    return f"{hour % 12 or 12}{'a' if hour < 12 else 'p'}"


async def place_forecast(name: str, start: datetime) -> Optional[dict]:
    """24 hourly points from Open-Meteo, in the bot's timezone. None when the place or the hours are thin."""
    geo = await cached_json(GEOCODE, {"name": name, "count": 1}, 86400 * 7)
    results = [r for r in (geo.get("results") or []) if _place_close(name, r)]
    if not results:
        return None
    hit = results[0]
    lat, lon = hit["latitude"], hit["longitude"]
    label = hit.get("name") or name
    admin = hit.get("admin1")
    place = f"{label}, {admin}" if admin else label
    tzname = getattr(TZ, "key", None) or "America/Chicago"
    day0 = start.astimezone(TZ).date()
    fc = await cached_json(FORECAST, {
        "latitude": lat, "longitude": lon, "timezone": tzname,
        "start_date": day0.isoformat(), "end_date": (day0 + timedelta(days=1)).isoformat(),
        "temperature_unit": "fahrenheit", "wind_speed_unit": "mph",
        "hourly": "temperature_2m,precipitation_probability,wind_speed_10m",
    }, 1800)
    hourly = fc.get("hourly") or {}
    times = hourly.get("time") or []
    temps = hourly.get("temperature_2m") or []
    rains = hourly.get("precipitation_probability") or []
    winds = hourly.get("wind_speed_10m") or []
    stamp = start.astimezone(TZ).strftime("%Y-%m-%dT%H:00")
    later = [i for i, t in enumerate(times) if t >= stamp]
    if not later:
        return None
    hours = []
    for i in range(later[0], min(later[0] + 24, len(times))):
        if i >= len(temps) or temps[i] is None:
            continue
        hours.append({
            "label": _hour_label(times[i]),
            "temp": float(temps[i]),
            "rain": float(rains[i]) if i < len(rains) and rains[i] is not None else 0.0,
            "wind": float(winds[i]) if i < len(winds) and winds[i] is not None else 0.0,
        })
    if len(hours) < 4:
        return None
    return {"place": place, "matched": label, "hours": hours, "game": None, "note": None}


def weather_brief(pack: dict) -> str:
    hours = pack.get("hours") or []
    if not hours:
        return ""
    temps = [h["temp"] for h in hours]
    rains = [h.get("rain") or 0 for h in hours]
    peak = rains.index(max(rains))
    bits = [str(pack.get("place") or "")]
    if pack.get("game"):
        bits.append(str(pack["game"]))
    bits.append(f"Now {temps[0]:.0f}°F, high {max(temps):.0f}°, low {min(temps):.0f}°.")
    bits.append(f"Rain peaks at {rains[peak]:.0f}% around {hours[peak].get('label')}.")
    bits.append(f"Wind now {hours[0].get('wind') or 0:.0f} mph.")
    if pack.get("note"):
        bits.append(str(pack["note"]))
    return " ".join(b for b in bits if b)


async def answer_weather(question: str) -> Optional[dict]:
    """Hourly forecast for a named city, a team's next outdoor city, or Chicago when no place was named."""
    now = datetime.now(TZ)
    start = now
    if re.search(r"\btomorrow\b", question or "", re.I):
        start = (now + timedelta(days=1)).replace(hour=12, minute=0, second=0, microsecond=0)
    phrase = weather_place_phrase(question)
    pack = None
    aside = None
    if phrase:
        pack = await place_forecast(phrase, start)
        exact = bool(pack and phrase.lower() in (pack.get("matched") or "").lower())
        if not exact:
            found = None
            try:
                found = await asyncio.wait_for(next_game(phrase, list(LEAGUE_SLUGS)), timeout=4)
            except Exception:
                log.warning("Weather team lookup failed for %s", phrase)
            if found:
                _path, ev, _i = found
                venue = ev.get("venue") or {}
                city = venue.get("city") or ""
                game = short_game(ev)
                note = None
                if venue.get("indoor"):
                    note = f"Indoors. This is the outdoor forecast for {city or 'that city'}."
                    aside = note
                when = event_time(ev) or start
                game_pack = await place_forecast(city, when) if city else None
                if game_pack:
                    game_pack["game"] = game
                    game_pack["note"] = note
                    pack = game_pack
    if pack is None:
        pack = await place_forecast("Chicago", start)
        if pack is None:
            return None
        base = ("No city was named, so this is Chicago." if not phrase
                else f"Couldn't match {phrase}, so this is Chicago.")
        pack["note"] = f"{aside} {base}" if aside else base
    pack["brief"] = weather_brief(pack)
    pack["now"] = pack["hours"][0]["temp"]
    return pack


