def persona(guild_id: int) -> str:
    p = get_setting(guild_id, "persona") or "default"
    return p if p in PERSONAS else "default"


def persona_prompt(guild_id: int) -> str:
    return PERSONAS[persona(guild_id)][1]


def voice_line(guild_id: int, kind: str, **kw) -> Optional[str]:
    options = LINES[kind].get(persona(guild_id)) or LINES[kind]["default"]
    choice = _random.choice(options)
    if choice is None:
        return None
    try:
        return choice.format(**kw)
    except (KeyError, IndexError):
        return LINES[kind]["default"][0].format(**kw) if LINES[kind]["default"][0] else None


LINE_SYSTEM = """You write ONE short Discord message (max 30 words) reacting to a friend's sports bet result in \
a group chat of friends who track their picks. Voice: {voice}.
Rules: talk about the bet only. Never mention odds, prices or line movement. Never encourage betting more, \
chasing losses or bigger stakes. No hashtags. At most two emojis. Output only the message."""


async def persona_reaction(guild_id: int, kind: str, facts: str, fallback: str) -> str:
    """A fresh line from Claude in the server's voice; the template if Claude isn't set up, is slow, or the day's cap is hit."""
    if not ai_enabled() or not claude_budget_ok():
        return fallback
    try:
        reply = await asyncio.wait_for(anthropic_client().messages.create(
            model=CLAUDE_MODEL, max_tokens=120, system=LINE_SYSTEM.format(voice=persona_prompt(guild_id)),
            messages=[{"role": "user", "content": f"{'Celebrate this win' if kind == 'cash' else 'Roast this loss (they asked to be roasted)'}:\n{facts}"}]),
            timeout=8)
        text = "".join(b.text for b in reply.content if getattr(b, "type", "") == "text").strip().strip('"')
        return clip(text, 300) if text else fallback
    except Exception:
        log.warning("Reaction line failed; using a template", exc_info=True)
        return fallback


# ---- where a pick's card lives (so reactions and receipts can reply/edit) --------------------------

def _ensure_r14_tables():
    db().executescript("""
        CREATE TABLE IF NOT EXISTS pick_msgs (
            pick_id    INTEGER PRIMARY KEY,
            guild_id   INTEGER NOT NULL,
            channel_id INTEGER NOT NULL,
            message_id INTEGER NOT NULL,
            receipt    INTEGER NOT NULL DEFAULT 0,
            sig        TEXT,
            updated_at TEXT,
            done       INTEGER NOT NULL DEFAULT 0
        );
    """)
    cols = {r[1] for r in db().execute("PRAGMA table_info(picks)")}
    if "cheered" not in cols:
        db().execute("ALTER TABLE picks ADD COLUMN cheered INTEGER")
    db().commit()


_r14_ready = False


def r14_db():
    global _r14_ready
    if not _r14_ready:
        _ensure_r14_tables()
        _r14_ready = True
    return db()


def remember_pick_msg(guild_id: int, pick_id: int, channel_id: int, message_id: int, receipt: bool = False):
    r14_db().execute("INSERT OR REPLACE INTO pick_msgs (pick_id, guild_id, channel_id, message_id, receipt, updated_at, done) "
                     "VALUES (?,?,?,?,?,?,0)", (pick_id, guild_id, channel_id, message_id, int(receipt), now_iso()))
    db().commit()


def pick_msg(pick_id: int):
    return r14_db().execute("SELECT * FROM pick_msgs WHERE pick_id = ?", (pick_id,)).fetchone()


# ---- personal reactions when a pick settles ---------------------------------------------------------

async def cheer_settled(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    since = iso(now - timedelta(hours=6))
    rows = r14_db().execute("SELECT * FROM picks WHERE status IN ('win', 'loss') AND settled_at >= ? AND cheered IS NULL "
                            "AND (hidden IS NULL OR hidden = 0 OR revealed_at IS NOT NULL) ORDER BY settled_at",
                            (since,)).fetchall()
    posted = 0
    for p in rows:
        if posted >= 5:   # the rest wait for the next run, so the scheduler never stalls on this
            break
        db().execute("UPDATE picks SET cheered = 1 WHERE id = ?", (p["id"],))
        db().commit()
        gid = p["guild_id"]
        if get_setting(gid, "reactions") == "off":
            continue
        roast = p["status"] == "loss"
        if roast and get_setting(gid, f"roast:{p['bettor_key']}") != "on":
            continue
        if not roast and p["cost"] and (p["returned"] or 0) >= 10 * p["cost"]:
            continue   # the big-win banner already covers this one
        target = pick_msg(p["id"])
        ids = (target["channel_id"], target["message_id"]) if target else jump_ids(p["slip_url"])
        channel = client.get_channel(ids[0]) if ids else None
        if channel is None:
            continue
        posted += 1
        legs = get_legs(p["id"])
        missed = next((x["text"] for x in legs if x["status"] == "miss"), None)
        amount = signed(pick_net(p)) if not roast else money(p["cost"])
        kw = dict(name=call_name(gid, p["bettor_key"], p["bettor_name"]), amount=amount, desc=clip(p["description"], 60),
                  leg=clip(missed or "it", 50),
                  payout=money(p["payout"]), mult=f"{(p['returned'] or 0) / p['cost']:.1f}" if p["cost"] else "?",
                  cost=money(p["cost"]), n=len(legs), pid=p["id"])
        fallback = voice_line(gid, "roast" if roast else "cash", **kw)
        streak = current_streak(gid, p["bettor_key"])
        facts = (f"Bettor: {kw['name']}\nPlay: {p['description']} on {p['platform']}"
                 + (f" ({p['sport']})" if p["sport"] else "")
                 + f"\nRisked {money(p['cost'])}, " + (f"won {signed(pick_net(p))}" if not roast else "lost it")
                 + (f"\nLegs: " + "; ".join(f"{x['text']} ({x['status']})" for x in legs[:8]) if legs else "")
                 + (f"\nCurrent streak: {streak.lstrip('🔥🧊')}" if streak else ""))
        line = (None if roast else hype_line(gid, p, kw)) or \
            await persona_reaction(gid, "roast" if roast else "cash", facts, fallback)
        line = with_memory(gid, p, line)
        if channel is not None:
            try:
                ref = channel.get_partial_message(ids[1])
                ref = ref.to_reference(fail_if_not_exists=False) if hasattr(ref, "to_reference") else ref
                await channel.send(line, reference=ref, mention_author=False,
                                   allowed_mentions=discord.AllowedMentions.none())
            except TypeError:
                await channel.send(line, allowed_mentions=discord.AllowedMentions.none())
            except Exception:
                log.warning("Couldn't post the reaction for pick %s", p["id"])
        if not roast:
            await voice_say(client, gid, re.sub(r"[*_`]|<[^>]+>", "", line))


# ---- heads-up when logging a pick ---------------------------------------------------------------------

_PROP_CACHE: dict[str, Optional[dict]] = {}


def cached_prop(text: str) -> Optional[dict]:
    if text not in _PROP_CACHE:
        if len(_PROP_CACHE) > 20000:
            _PROP_CACHE.clear()
        try:
            _PROP_CACHE[text] = prop_of(text)
        except Exception:
            _PROP_CACHE[text] = None
    return _PROP_CACHE[text]


def _rate_line(label: str, good: int, bad: int, legs: bool) -> str:
    pct = good / (good + bad) * 100
    return (f"hit **{good} of {good + bad}** {label} ({pct:.0f}%)" if legs else
            f"**{good}-{bad}** on {label} ({pct:.0f}%)")


def headsup_lines(guild_id: int, key: str, p) -> list[str]:
    """Up to two things the bettor's own history says about this kind of pick."""
    # the most recent history only: it's what "lately" means, and it keeps this quick for heavy bettors
    settled = [x for x in db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_key = ? AND status IN "
                                       "('win', 'loss') AND id != ? ORDER BY id DESC LIMIT 400",
                                       (guild_id, key, p["id"]))]
    legs_hist = db().execute("""SELECT l.text, l.status FROM legs l JOIN picks q ON q.id = l.pick_id
                                WHERE q.guild_id = ? AND q.bettor_key = ? AND l.status IN ('hit', 'miss')
                                AND q.id != ? ORDER BY l.id DESC LIMIT 300""", (guild_id, key, p["id"])).fetchall()
    found = []  # (strength, line, bad?)
    if len(settled) >= 8:
        base = sum(1 for x in settled if x["status"] == "win") / len(settled)
        n_legs = len(get_legs(p["id"])) or 1
        slices = []
        if p["sport"]:
            g = sport_group(p["sport"])
            slices.append((f"{g} picks", [x for x in settled if sport_group(x["sport"]) == g]))
        slices.append((f"{p['platform']} picks", [x for x in settled if x["platform"] == p["platform"]]))
        sz = size_group(n_legs)
        all_legs = legs_by_pick(guild_id, key)
        counts = {x["id"]: len(all_legs.get(x["id"], [])) or 1 for x in settled}
        slices.append((f"{sz.lower()} slips" if sz != "Single" else "single picks",
                       [x for x in settled if size_group(counts[x["id"]]) == sz]))
        day = datetime.now(TZ).strftime("%A")
        slices.append((f"{day}s", [x for x in settled
                                   if datetime.fromisoformat(x["created_at"]).astimezone(TZ).strftime("%A") == day]))
        for label, rows in slices:
            n = len(rows)
            if n < 8 or n == len(settled):
                continue
            w = sum(1 for x in rows if x["status"] == "win")
            rate = w / n
            if abs(rate - base) >= 0.15:
                found.append((abs(rate - base) * n ** 0.5, _rate_line(label, w, n - w, False), rate < base))
    if len(legs_hist) >= 10:
        parsed = [(cached_prop(x["text"]), x["status"]) for x in legs_hist]
        base = sum(1 for _, s in parsed if s == "hit") / len(parsed)
        seen = set()
        for leg in get_legs(p["id"]):
            pr = cached_prop(leg["text"])
            if not pr:
                continue
            stat = pr["stats"][0]
            label = f"{STATS[stat][0]} {pr['side']}s"
            for lab, match in ((label, lambda q: q and q["stats"][0] == stat and q["side"] == pr["side"]),
                               (f"legs on {pr['display']}", lambda q: q and q["player"] == pr["player"])):
                if lab in seen:
                    continue
                seen.add(lab)
                rows = [s for q, s in parsed if match(q)]
                n = len(rows)
                if n < 6:
                    continue
                h = sum(1 for s in rows if s == "hit")
                rate = h / n
                if abs(rate - base) >= 0.15:
                    found.append((abs(rate - base) * n ** 0.5, _rate_line(lab, h, n - h, True), rate < base))
    found.sort(key=lambda x: -x[0])
    return [("⚠️ " if bad else "✅ ") + "You've " + line + "." for _, line, bad in found[:2]]


def headsup_text(guild_id: int, key: str, pick_id: int) -> Optional[str]:
    if key.startswith("label:") or get_setting(guild_id, f"headsup:{key}") == "off":
        return None
    p = get_pick(guild_id, pick_id)
    if p is None:
        return None
    try:
        lines = headsup_lines(guild_id, key, p)
    except Exception:
        log.exception("Heads-up failed")
        return None
    if not lines:
        return None
    return ("🧠 **Heads-up from your own history** (only you see this):\n" + "\n".join(lines) +
            "\n-# Turn these off with `/me headsup`.")


# ---- the trading card ----------------------------------------------------------------------------

def card_numbers(guild_id: int, key: str) -> Optional[dict]:
    stats = compute_stats(guild_id, key)
    if not stats:
        return None
    s = stats[0]
    settled = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_key = ? AND status != 'open' "
                           "ORDER BY settled_at, id", (guild_id, key)).fetchall()
    lc = leg_counts(guild_id, key)
    graded = lc["hit"] + lc["miss"]
    leg_rate = lc["hit"] / graded if graded else None
    n = s["wins"] + s["losses"]
    last10 = [p["status"] for p in settled if p["status"] in ("win", "loss")][-10:]
    wins = [p for p in settled if p["status"] == "win" and p["cost"]]
    best_mult = max(((p["returned"] or 0) / p["cost"] for p in wins), default=0)
    all_legs = legs_by_pick(guild_id, key)
    avg_legs = (sum(len(all_legs.get(p["id"], [])) or 1 for p in settled) / len(settled)) if settled else 0
    avg_mult = (sum(p["payout"] / p["cost"] for p in settled if p["cost"]) / len(settled)) if settled else 0
    # rating: legs hit, ROI and recent form, pulled toward 60 until there's a real sample
    leg_score = max(0.0, min(1.0, ((leg_rate if leg_rate is not None else 0.5) - 0.40) / 0.30))
    roi_score = max(0.0, min(1.0, (s["roi"] + 50) / 100))
    form_score = max(0.0, min(1.0, (sum(1 for x in last10 if x == "win") / len(last10)) / 0.6)) if last10 else 0.5
    raw = 50 + 49 * (0.45 * leg_score + 0.35 * roi_score + 0.20 * form_score)
    w = n / (n + 15)
    ovr = int(round(max(40, min(99, 60 + (raw - 60) * w))))
    wins10 = sum(1 for x in last10 if x == "win")
    if n < 5:
        title = "Rookie Card"
    elif len(last10) >= 6 and wins10 >= 7:
        title = "On Fire"
    elif len(last10) >= 6 and wins10 == 0:
        title = "Ice Cold"
    elif s["roi"] >= 25 and n >= 20:
        title = "The Oracle"
    elif avg_mult >= 10:
        title = "Longshot Hunter"
    elif avg_legs >= 4.5:
        title = "Parlay Merchant"
    elif leg_rate is not None and leg_rate >= 0.6 and graded >= 30:
        title = "Prop Sniper"
    elif s["net"] >= 0:
        title = "In the Green"
    else:
        title = "Still Cooking"
    groups = breakdown(settled, lambda p: sport_group(p["sport"]))
    top_sport = groups[0][0] if groups and groups[0][0] != "No sport" else None
    first = db().execute("SELECT MIN(id) AS m FROM picks WHERE guild_id = ? AND bettor_key = ?", (guild_id, key)).fetchone()["m"]
    return {"s": s, "settled": settled, "leg_rate": leg_rate, "n": n, "ovr": ovr, "title": title, "legs": all_legs,
            "rarity": rarity_for(ovr, n), "best_mult": best_mult, "groups": groups, "top_sport": top_sport,
            "serial": f"#{first:04d}" if first else ""}


def card_payload(guild_id: int, key: str, name: str, back: bool = False) -> Optional[dict]:
    cn = card_numbers(guild_id, key)
    if cn is None:
        return None
    s = cn["s"]
    green, red = ART_GREEN, ART_RED
    streak = current_streak(guild_id, key).lstrip("🔥🧊")
    stats = [("WIN %", f"{s['wins'] / cn['n'] * 100:.0f}%" if cn["n"] else "-", None),
             ("ROI", f"{s['roi']:+.1f}%", green if s["roi"] >= 0 else red),
             ("LEGS HIT", f"{cn['leg_rate'] * 100:.0f}%" if cn["leg_rate"] is not None else "-", None),
             ("NET", signed_short(s["net"]), green if s["net"] >= 0 else red),
             ("STREAK", streak or "-", green if streak.startswith("W") else red if streak.startswith("L") else None),
             ("BEST", f"{cn['best_mult']:.0f}x" if cn["best_mult"] else "-", ART_AMBER if cn["best_mult"] >= 5 else None)]
    got = earned_badges(guild_id, key)
    tag = " · ".join(x for x in ((get_setting(guild_id, f"cardtitle:{key}") or ""),
                                 (get_bio(guild_id, int(key)).get("tagline") if key.isdigit() else "") or "") if x)
    c = {"name": s["name"] or name, "ovr": cn["ovr"], "rarity": cn["rarity"], "title": cn["title"],
         "sport": cn["top_sport"], "stats": stats, "badges": [n for k, n, _ in BADGES if k in got], "tagline": tag,
         "serial": cn["serial"], "season": str(datetime.now(TZ).year), "back": back,
         "theme": theme_for(guild_id, int(key)) if key.isdigit() else None}
    if back:
        rows = []
        for g, v in cn["groups"][:3]:
            if g == "No sport":
                continue
            rows.append((g, f"{v['w']}-{v['l']} · {signed_short(v['net'])}"))
        plats = breakdown(cn["settled"], lambda p: p["platform"])
        if plats:
            rows.append(("Favorite app", plats[0][0]))
        players: dict[str, int] = {}
        for x in db().execute("SELECT l.text FROM legs l JOIN picks q ON q.id = l.pick_id WHERE q.guild_id = ? "
                              "AND q.bettor_key = ? AND (q.hidden IS NULL OR q.hidden = 0 OR q.revealed_at IS NOT NULL)",
                              (guild_id, key)):
            pr = cached_prop(x["text"])
            if pr:
                players[pr["display"]] = players.get(pr["display"], 0) + 1
        if players:
            top = max(players.items(), key=lambda kv: kv[1])
            rows.append(("Most played", f"{top[0]} ({top[1]} legs)"))
        wins = [p for p in cn["settled"] if p["status"] == "win"]
        if wins:
            b = max(wins, key=pick_net)
            rows.append(("Best hit", f"{signed_short(pick_net(b))} on {clip(b['description'], 26)}"))
        heart = sum(1 for p in cn["settled"] if p["status"] == "loss"
                    and sum(1 for x in cn["legs"].get(p["id"], []) if x["status"] == "miss") == 1
                    and len(cn["legs"].get(p["id"], [])) >= 3)
        if heart:
            rows.append(("Lost by one leg", f"{heart}×"))
        lines = []
        parsed = [(cached_prop(x["text"]), x["status"]) for x in db().execute(
            "SELECT l.text, l.status FROM legs l JOIN picks q ON q.id = l.pick_id WHERE q.guild_id = ? AND "
            "q.bettor_key = ? AND l.status IN ('hit','miss') AND (q.hidden IS NULL OR q.hidden = 0 OR q.revealed_at IS NOT NULL)",
            (guild_id, key))]
        for side in ("over", "under"):
            xs = [s2 for q, s2 in parsed if q and q["side"] == side]
            if len(xs) >= 5:
                lines.append(f"Hits {sum(1 for v in xs if v == 'hit') / len(xs) * 100:.0f}% of {side}s ({len(xs)} legs)")
        days = breakdown(cn["settled"], lambda p: datetime.fromisoformat(p["created_at"]).astimezone(TZ).strftime("%A"))
        days = [(d, v) for d, v in days if v["w"] + v["l"] >= 4]
        if days:
            best = max(days, key=lambda kv: kv[1]["w"] / (kv[1]["w"] + kv[1]["l"]))
            worst = min(days, key=lambda kv: kv[1]["w"] / (kv[1]["w"] + kv[1]["l"]))
            lines.append(f"Best day: {best[0]} ({best[1]['w']}-{best[1]['l']})")
            if worst[0] != best[0]:
                lines.append(f"Coldest day: {worst[0]} ({worst[1]['w']}-{worst[1]['l']})")
        lines = lines[:6]
        if key.isdigit():
            pr_ = pass_record(guild_id, int(key))
            if pr_["good"] + pr_["bad"]:
                lines.append(f"Passes: {pr_['good']} good, {pr_['bad']} would've hit")
        lines.append(f"Card rating {cn['ovr']} · {cn['rarity'][0]} · {cn['n']} settled picks")
        c["back_rows"], c["back_lines"] = rows, lines
    return c


_AVATAR_CACHE: dict[int, tuple[float, Optional[bytes]]] = {}


async def avatar_bytes(user) -> Optional[bytes]:
    if user is None:
        return None
    uid = getattr(user, "id", None)
    hit = _AVATAR_CACHE.get(uid)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    raw = await fetch_avatar(user)
    _AVATAR_CACHE[uid] = (time.monotonic() + (6 * 3600 if raw else 600), raw)
    return raw


class CardFlipButton(discord.ui.Button):
    def __init__(self, key: str, name: str, user, back: bool = False):
        super().__init__(label="🔄 Front" if back else "🔄 Flip", style=discord.ButtonStyle.secondary)
        self.key, self.name, self.user, self.back = key, name, user, back

    async def callback(self, interaction: discord.Interaction):
        if await sec_button_slow(interaction, "card_flip", "render"):
            return
        await interaction.response.defer()
        self.back = not self.back
        self.label = "🔄 Front" if self.back else "🔄 Flip"
        c = card_payload(interaction.guild_id, self.key, self.name, back=self.back)
        if c is None:
            return
        av = await avatar_bytes(self.user)
        png = await asyncio.to_thread(locked_render, render_trading_card, c, av)
        await interaction.edit_original_response(attachments=[discord.File(png, filename="card.png")],
                                                 view=getattr(self, "parent_view", None) or self.view)


def CardFlipView(key: str, name: str, user, back: bool = False) -> discord.ui.View:
    v = discord.ui.View(timeout=1800)
    b = CardFlipButton(key, name, user, back)
    v.add_item(b)
    b.parent_view = v
    return v


# ---- personal milestones -----------------------------------------------------------------------------

PICK_MILESTONES = (100, 250, 500, 1000)
_PM_SNAPSHOT: dict[tuple, tuple] = {}


async def personal_milestones(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    local = now.astimezone(TZ)
    since = iso(now - timedelta(hours=6))
    for r in db().execute("SELECT guild_id, value FROM settings WHERE key = 'recap_channel'").fetchall():
        gid = r["guild_id"]
        channel = client.get_channel(int(r["value"]))
        keys = [x["bettor_key"] for x in db().execute("SELECT DISTINCT bettor_key FROM picks WHERE guild_id = ?", (gid,))]
        first_run = get_setting(gid, "pm_init") is None
        if first_run:
            set_setting(gid, "pm_init", now_iso())
        out = []
        snap = {r2["bettor_key"]: (r2["n"], r2["m"], r2["s"]) for r2 in db().execute(
            "SELECT bettor_key, COUNT(*) AS n, MAX(id) AS m, MAX(settled_at) AS s FROM picks WHERE guild_id = ? "
            "GROUP BY bettor_key", (gid,))}
        for key in keys:
            if not first_run and _PM_SNAPSHOT.get((gid, key)) == snap.get(key):
                continue   # nothing new for this bettor since the last run
            _PM_SNAPSHOT[(gid, key)] = snap.get(key)
            name_row = db().execute("SELECT bettor_name FROM picks WHERE guild_id = ? AND bettor_key = ? ORDER BY id DESC "
                                    "LIMIT 1", (gid, key)).fetchone()
            who = f"<@{key}>" if key.isdigit() else f"**{name_row['bettor_name']}**"
            total = db().execute("SELECT COUNT(*) AS n FROM picks WHERE guild_id = ? AND bettor_key = ?", (gid, key)).fetchone()["n"]
            reached = max([m for m in PICK_MILESTONES if total >= m], default=0)
            prev = int(get_setting(gid, f"pmcount:{key}") or 0)
            if reached > prev:
                set_setting(gid, f"pmcount:{key}", str(reached))
                newest = db().execute("SELECT created_at, import_key FROM picks WHERE guild_id = ? AND bettor_key = ? "
                                      "ORDER BY id DESC LIMIT 1", (gid, key)).fetchone()
                fresh = newest and not newest["import_key"] and newest["created_at"] >= since
                if not first_run and fresh:
                    s = compute_stats(gid, key)[0]
                    out.append(f"📒 {who} just logged pick **#{reached}**. Lifetime: {record_line(s)}, {signed(s['net'])}.")
            wins = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_key = ? AND status = 'win'",
                                (gid, key)).fetchall()
            if wins:
                best = max(wins, key=pick_net)
                prev_pb = get_setting(gid, f"pb:{key}")
                if prev_pb is None or first_run:
                    set_setting(gid, f"pb:{key}", f"{pick_net(best):.2f}")
                elif pick_net(best) > float(prev_pb) + 0.005:
                    set_setting(gid, f"pb:{key}", f"{pick_net(best):.2f}")
                    if len(wins) >= 6 and (best["settled_at"] or "") >= since and \
                            (not best["hidden"] or best["revealed_at"]):
                        out.append(f"🏆 New personal best for {who}: **{signed(pick_net(best))}** on "
                                   f"{clip(best['description'], 70)}.")
            last_settle = db().execute("SELECT MAX(settled_at) AS m FROM picks WHERE guild_id = ? AND bettor_key = ?",
                                       (gid, key)).fetchone()["m"] or ""
            changed = last_settle != (get_setting(gid, f"pmseen:{key}") or "")
            if changed:
                set_setting(gid, f"pmseen:{key}", last_settle or None)
            if changed or first_run:
                cn = card_numbers(gid, key)
                if cn:
                    tier = [x[0] for x in RARITIES].index(cn["rarity"][0])
                    prev_t = get_setting(gid, f"tier:{key}")
                    if prev_t is None or first_run:
                        set_setting(gid, f"tier:{key}", str(tier))
                    elif tier > int(prev_t):
                        set_setting(gid, f"tier:{key}", str(tier))
                        out.append(f"🃏 {who}'s card just upgraded to **{cn['rarity'][0].upper()}** (OVR {cn['ovr']}). "
                                   "`/card` to see it.")
        # once a day: pickiversaries and birthdays
        today = local.date().isoformat()
        if local.hour >= 10 and get_setting(gid, "pm_day") != today:
            set_setting(gid, "pm_day", today)
            if not first_run:
                for key in keys:
                    first = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_key = ? ORDER BY created_at "
                                         "LIMIT 1", (gid, key)).fetchone()
                    d0 = datetime.fromisoformat(first["created_at"]).astimezone(TZ).date()
                    if d0.month == local.month and d0.day == local.day and d0.year < local.year:
                        yrs = local.year - d0.year
                        s = compute_stats(gid, key)[0]
                        who = f"<@{key}>" if key.isdigit() else f"**{first['bettor_name']}**"
                        out.append(f"📅 Happy pickiversary {who}! {yrs} year{'s' if yrs != 1 else ''} since your first "
                                   f"pick. Since then: {record_line(s)}, {signed(s['net'])}.")
                import calendar
                bday_today = {local.strftime("%m-%d")}
                if local.strftime("%m-%d") == "02-28" and not calendar.isleap(local.year):
                    bday_today.add("02-29")
                for b in db().execute("SELECT key, value FROM settings WHERE guild_id = ? AND key LIKE 'bday:%'", (gid,)):
                    if b["value"] in bday_today:
                        uid = b["key"].split(":", 1)[1]
                        line = f"🎂 Happy birthday <@{uid}>! 🎉"
                        wins = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_key = ? AND status = 'win'",
                                            (gid, uid)).fetchall()
                        if wins:
                            best = max(wins, key=pick_net)
                            line += f" Still thinking about that {signed(pick_net(best))} on {clip(best['description'], 50)}."
                        out.append(line)
        if channel is not None:
            for line in out:
                await channel.send(line, allowed_mentions=discord.AllowedMentions(everyone=False, roles=False, users=True))


# ---- asking about the group's own data --------------------------------------------------------------

ASK_DATA: contextvars.ContextVar = contextvars.ContextVar("ask_data", default=None)

DATA_TOOL = {
    "name": "group_stats",
    "description": ("Look up this Discord group's own logged betting records (their picks and parlay legs). Use it for "
                    "ANY question about the group's or a member's results, records, profit, hit rates, tendencies, or "
                    "who is best/worst at something. Every number you state about the group must come from this tool. "
                    "Pick-level results (W-L, profit) unless you filter or group by stat/side/player, which switches to "
                    "leg-level hit rates."),
    "input_schema": {
        "type": "object",
        "properties": {
            "bettor": {"type": "string", "description": "A member's name, or 'me' for the person asking. Omit for everyone."},
            "sport": {"type": "string", "description": "e.g. NFL, NBA, CS2, Soccer"},
            "platform": {"type": "string", "description": "e.g. PrizePicks, Kalshi, Sportsbook"},
            "since_days": {"type": "integer", "description": "Only the last N days (e.g. 30 for 'this month')"},
            "stat": {"type": "string", "description": "A prop stat like 'rebounds', 'pass yards', 'PRA'"},
            "side": {"type": "string", "enum": ["over", "under"]},
            "player": {"type": "string", "description": "A player name, for legs on that player"},
            "group_by": {"type": "string", "enum": ["none", "bettor", "sport", "platform", "month", "weekday", "stat",
                                                    "side", "player", "legs"]},
            "chart": {"type": "boolean", "description": "true to attach a bar chart of the groups"},
        },
    },
}


def _find_bettor(guild_id: int, text: str, asker_key: str) -> Optional[tuple[str, str]]:
    t = (text or "").strip().lower()
    if t in ("me", "my", "myself", "i", "mine"):
        row = db().execute("SELECT bettor_name FROM picks WHERE guild_id = ? AND bettor_key = ? ORDER BY id DESC LIMIT 1",
                           (guild_id, asker_key)).fetchone()
        return asker_key, row["bettor_name"] if row else "you"
    best = None
    for s in compute_stats(guild_id):
        n = (s["name"] or "").lower()
        if n == t:
            return s["key"], s["name"]
        if t and (t in n or n in t) and best is None:
            best = (s["key"], s["name"])
    return best


def run_group_stats(guild_id: int, asker_key: str, args: dict) -> dict:
    args = {k: v for k, v in (args or {}).items() if v not in (None, "", "none")}
    group_by = args.get("group_by", "none")
    leg_level = bool(args.get("stat") or args.get("side") or args.get("player")) or group_by in ("stat", "side", "player")
    since = iso(datetime.now(timezone.utc) - timedelta(days=int(args["since_days"]))) if args.get("since_days") else None
    who = None
    if args.get("bettor"):
        who = _find_bettor(guild_id, args["bettor"], asker_key)
        if who is None:
            names = [s["name"] for s in compute_stats(guild_id)]
            return {"error": f"No member called {args['bettor']!r}. Members: {', '.join(names[:30])}"}
    picks = db().execute("SELECT * FROM picks WHERE guild_id = ? AND status != 'open' AND (hidden IS NULL OR hidden = 0 "
                         "OR revealed_at IS NOT NULL)", (guild_id,)).fetchall()

    def keep(p) -> bool:
        if who and p["bettor_key"] != who[0]:
            return False
        if since and (p["settled_at"] or "") < since:
            return False
        if args.get("sport") and args["sport"].lower() not in (sport_group(p["sport"]) + " " + (p["sport"] or "")).lower():
            return False
        if args.get("platform") and args["platform"].lower() not in (p["platform"] or "").lower():
            return False
        return True

    picks = [p for p in picks if keep(p)]
    out: dict = {"filters": {k: v for k, v in args.items() if k != "chart"}, "level": "legs" if leg_level else "picks"}
    if who:
        out["filters"]["bettor"] = who[1]
    if not leg_level:
        def kfn(p):
            if group_by == "bettor":
                return p["bettor_name"]
            if group_by == "sport":
                return sport_group(p["sport"])
            if group_by == "platform":
                return p["platform"]
            if group_by == "month":
                return (p["settled_at"] or p["created_at"])[:7]
            if group_by == "weekday":
                return datetime.fromisoformat(p["created_at"]).astimezone(TZ).strftime("%A")
            if group_by == "legs":
                return size_group(len(get_legs(p["id"])) or 1)
            return "all"
        groups = breakdown(picks, kfn)
        rows = []
        for g, v in groups:
            n = v["w"] + v["l"]
            rows.append({"group": g, "record": f"{v['w']}-{v['l']}" + (f"-{v['p']}" if v["p"] else ""),
                         "win_pct": round(v["w"] / n * 100, 1) if n else None, "net": round(v["net"], 2),
                         "staked": round(v["staked"], 2), "roi_pct": round(v["net"] / v["staked"] * 100, 1) if v["staked"] else None})
        if group_by in ("month",):
            rows.sort(key=lambda r: r["group"])
        elif group_by != "none":
            rows.sort(key=lambda r: -r["net"])
        out["groups"] = rows[:15]
        out["chart_metric"] = "net"
    else:
        ids = {p["id"]: p for p in picks}
        legs = [x for x in db().execute("SELECT l.pick_id, l.text, l.status FROM legs l JOIN picks q ON q.id = l.pick_id "
                                        "WHERE q.guild_id = ? AND l.status IN ('hit', 'miss')", (guild_id,))
                if x["pick_id"] in ids]
        want_stats = set(stat_keys_in(args["stat"])) if args.get("stat") else None
        want_player = norm_name(args["player"]) if args.get("player") else None
        groups: dict[str, list[int]] = {}
        for x in legs:
            pr = cached_prop(x["text"])
            if (want_stats or args.get("side") or want_player or group_by in ("stat", "side", "player")) and not pr:
                continue
            if want_stats and not (set(pr["stats"]) & want_stats):
                continue
            if args.get("side") and pr["side"] != args["side"]:
                continue
            if want_player and want_player not in pr["player"]:
                continue
            p = ids[x["pick_id"]]
            g = {"bettor": p["bettor_name"], "sport": sport_group(p["sport"]), "platform": p["platform"],
                 "month": (p["settled_at"] or p["created_at"])[:7],
                 "weekday": datetime.fromisoformat(p["created_at"]).astimezone(TZ).strftime("%A"),
                 "stat": STATS[pr["stats"][0]][0] if pr else "?", "side": pr["side"] if pr else "?",
                 "player": pr["display"] if pr else "?"}.get(group_by, "all")
            c = groups.setdefault(g, [0, 0])
            c[0 if x["status"] == "hit" else 1] += 1
        rows = [{"group": g, "hit": h, "miss": m, "hit_pct": round(h / (h + m) * 100, 1)} for g, (h, m) in groups.items()]
        rows.sort(key=lambda r: r["group"] if group_by == "month" else -(r["hit"] + r["miss"]))
        if group_by in ("bettor", "player", "stat") and len(rows) > 1:
            rows = [r for r in rows if r["hit"] + r["miss"] >= 3] or rows
            rows.sort(key=lambda r: -r["hit_pct"])
        out["groups"] = rows[:15]
        out["chart_metric"] = "hit_pct"
    if not out["groups"]:
        out["note"] = "Nothing matches those filters."
    return out


def render_bars(title: str, labels: list[str], values: list[float], pct: bool) -> io.BytesIO:
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    fig, ax = plt.subplots(figsize=(9, max(2.6, 0.5 * len(labels) + 1.2)), dpi=110)
    fig.patch.set_facecolor(CHART_SURFACE)
    ax.set_facecolor(CHART_SURFACE)
    ys = list(range(len(labels)))[::-1]
    colors = [("#3fb97a" if v >= (50 if pct else 0) else "#e66767") for v in values]
    ax.barh(ys, values, color=colors, height=0.62)
    ax.set_yticks(ys)
    ax.set_yticklabels([clip(x, 30) for x in labels], color=CHART_TEXT, fontsize=11)
    ax.tick_params(axis="x", colors=CHART_MUTED)
    for sp in ax.spines.values():
        sp.set_visible(False)
    ax.axvline(50 if pct else 0, color=CHART_MUTED, linewidth=1, alpha=0.6)
    if pct:
        ax.set_xlim(0, 112)
    else:
        lo, hi = min(values + [0]), max(values + [0])
        pad = (hi - lo) * 0.18 or 10
        ax.set_xlim(lo - (pad if lo < 0 else 0), hi + pad)
    for y, v in zip(ys, values):
        ax.text(v, y, f" {v:.0f}%" if pct else f" {'+' if v >= 0 else '-'}${abs(v):,.0f}", va="center",
                ha="left" if v >= 0 else "right", color=CHART_TEXT, fontsize=10)
    ax.set_title(clip(title, 70), color=CHART_TEXT, fontsize=13, loc="left", fontweight="bold")
    ax.grid(axis="x", color=CHART_GRID, linewidth=0.6)
    ax.set_axisbelow(True)
    fig.tight_layout()
    out = io.BytesIO()
    fig.savefig(out, format="png", facecolor=CHART_SURFACE)
    plt.close(fig)
    out.seek(0)
    return out


def chart_from_result(res: dict) -> Optional[tuple]:
    rows = [r for r in res.get("groups") or [] if r.get("group") not in ("all",)]
    metric = res.get("chart_metric")
    if len(rows) < 2:
        return None
    vals = [r.get("net") if metric == "net" else r.get("hit_pct") for r in rows]
    if any(v is None for v in vals):
        return None
    f = res.get("filters") or {}
    bits = [f.get("bettor"), f.get("sport"), f.get("platform"), f.get("stat"), f.get("side") and f["side"] + "s",
            f.get("player"), f"last {f['since_days']} days" if f.get("since_days") else None]
    title = ("Profit" if metric == "net" else "Legs hit") + " by " + (f.get("group_by") or "group") + \
            (" · " + " · ".join(b for b in bits if b) if any(bits) else "")
    labels = [f"{r['group']} ({r['record']})" if metric == "net" else f"{r['group']} ({r['hit']}/{r['hit'] + r['miss']})"
              for r in rows]
    return title, labels, [float(v) for v in vals], metric != "net"


# ---- live receipts and the live board --------------------------------------------------------------

_PROGRESS_CACHE: dict[int, tuple[float, list]] = {}


async def cached_progress(p, ttl: float = 100) -> list[dict]:
    hit = _PROGRESS_CACHE.get(p["id"])
    if hit and hit[0] > time.monotonic():
        return hit[1]
    try:
        entries = await leg_progress(p)
    except Exception:
        log.exception("Progress failed for pick %s", p["id"])
        entries = [{"n": x["idx"], "text": x["text"], "status": x["status"], "live": None, "in_play": False,
                    "num": None, "sub": "", "event": None} for x in get_legs(p["id"])]
    _PROGRESS_CACHE[p["id"]] = (time.monotonic() + ttl, entries)
    if len(_PROGRESS_CACHE) > 500:
        for k in list(_PROGRESS_CACHE)[:250]:
            _PROGRESS_CACHE.pop(k, None)
    return entries


def db_entries(p) -> list[dict]:
    """Leg rows from the database only (no network), for settled picks and fallbacks."""
    return [{"n": x["idx"], "text": x["text"], "status": x["status"], "live": None, "in_play": False, "num": None,
             "sub": "", "event": None} for x in get_legs(p["id"])]


def receipt_sig(p, entries: list[dict]) -> str:
    """What's worth re-drawing for: results, who's ahead, stat numbers and scores (not the game clock)."""
    def score(sub: str) -> str:
        return (sub or "").split(" · ")[0] if any(ch.isdigit() for ch in (sub or "").split(" · ")[0]) else ""
    return json.dumps([p["status"], [(e.get("status"), e.get("live"), (e.get("num") or {}).get("value"),
                                      score(e.get("sub")) if not e.get("num") else "", bool(e.get("in_play")))
                                     for e in entries]], default=str)


def receipt_data(p, entries: list[dict], avatar: Optional[bytes]) -> dict:
    design_remember(p, entries)
    entries = design_enrich(p, entries)
    return {"name": p["bettor_name"], "avatar": avatar, "platform": p["platform"], "description": p["description"],
            "cost": p["cost"], "payout": p["payout"], "pick_id": p["id"], "status": p["status"], "net": pick_net(p),
            "legs": entries, "updated": datetime.now(TZ).strftime("%-I:%M %p"),
            "theme": theme_for(p["guild_id"], p["bettor_id"]) if p["bettor_id"] else None,
            "sport": p["sport"], "returned": p["returned"], "entry": entry_kind(p, max(1, len(entries))),
            "logged": design_when(p["created_at"]), "art": design_art(entries)}


async def receipt_file(client, p, entries: Optional[list] = None) -> discord.File:
    if entries is None:
        entries = await cached_progress(p) if p["status"] == "open" else db_entries(p)
    user = None
    if p["bettor_id"]:
        user = await known_user(client, p["bettor_id"])
    av = await avatar_bytes(user) if user is not None else None
    await design_fetch_art(design_enrich(p, entries))         # headshots and logos, before the render thread
    png = await asyncio.to_thread(locked_render, render_receipt, receipt_data(p, entries, av))
    return discord.File(png, filename=f"receipt_{p['id']}.png")


def receipt_embed(p, filename: str) -> discord.Embed:
    e = pick_embed(p)
    e.set_image(url=f"attachment://{filename}")
    return e


async def update_receipts(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    rows = r14_db().execute("SELECT * FROM pick_msgs WHERE receipt = 1 AND done = 0 ORDER BY updated_at LIMIT 12").fetchall()
    for r in rows:
        p = get_pick(r["guild_id"], r["pick_id"])
        if p is None:
            db().execute("UPDATE pick_msgs SET done = 1 WHERE pick_id = ?", (r["pick_id"],))
            db().commit()
            continue
        stale = datetime.fromisoformat(p["created_at"]) < now - timedelta(days=4)
        settled = p["status"] != "open"
        entries = db_entries(p) if settled or stale else await cached_progress(p)
        sig = receipt_sig(p, entries)
        done = 1 if settled or stale else 0
        if sig == r["sig"] and not done:
            db().execute("UPDATE pick_msgs SET updated_at = ? WHERE pick_id = ?", (now_iso(), r["pick_id"]))
            db().commit()
            continue
        db().execute("UPDATE pick_msgs SET updated_at = ? WHERE pick_id = ?", (now_iso(), r["pick_id"]))
        db().commit()
        channel = client.get_channel(r["channel_id"])
        if channel is None:
            if done:
                db().execute("UPDATE pick_msgs SET done = 1 WHERE pick_id = ?", (r["pick_id"],))
                db().commit()
            continue
        try:
            f = await receipt_file(client, p, entries)
            await channel.get_partial_message(r["message_id"]).edit(embed=receipt_embed(p, f.filename), attachments=[f])
            db().execute("UPDATE pick_msgs SET sig = ?, done = ? WHERE pick_id = ?", (sig, done, r["pick_id"]))
            db().commit()
        except (discord.NotFound, discord.Forbidden):
            db().execute("UPDATE pick_msgs SET done = 1 WHERE pick_id = ?", (r["pick_id"],))
            db().commit()
        except Exception:
            log.warning("Couldn't update the receipt for pick %s", p["id"], exc_info=True)


BOARD_HOURS = 10


def board_state(guild_id: int) -> Optional[dict]:
    raw = get_setting(guild_id, "board")
    return json.loads(raw) if raw else None


async def board_snapshot(client, guild_id: int) -> Optional[tuple]:
    """(png, live?, signature, count) for the group's open slips with games today, or None if there are none."""
    cutoff = iso(datetime.now(timezone.utc) - timedelta(days=3))
    picks = db().execute("SELECT * FROM picks WHERE guild_id = ? AND status = 'open' AND (hidden IS NULL OR hidden = 0) "
                         "AND created_at >= ? ORDER BY id DESC LIMIT 25", (guild_id, cutoff)).fetchall()
    # slips that finished in the last few hours stay on the board with their stamp
    picks = list(picks) + list(db().execute(
        "SELECT * FROM picks WHERE guild_id = ? AND status != 'open' AND (hidden IS NULL OR hidden = 0) AND settled_at >= ? "
        "AND id IN (SELECT pick_id FROM legs) ORDER BY settled_at DESC LIMIT 8",
        (guild_id, iso(datetime.now(timezone.utc) - timedelta(hours=BOARD_SETTLED_HOURS)))).fetchall())
    today = datetime.now(TZ).date()
    slips = []
    for p in picks:
        entries = await cached_progress(p) if p["status"] == "open" else db_entries(p)
        design_remember(p, entries)
        relevant = p["status"] != "open"
        for e in entries:
            ev = e.get("event")
            when = event_time(ev) if ev and ev.get("date") else None
            if e.get("in_play") or (when and when.astimezone(TZ).date() == today) or \
                    (e.get("status") != "open" and ev and ev.get("state") == "post"):
                relevant = True
        if not relevant:
            continue
        user = (await known_user(client, p["bettor_id"]) if p["bettor_id"] else None)
        slips.append({"name": p["bettor_name"], "avatar": await avatar_bytes(user) if user else None, "cost": p["cost"],
                      "payout": p["payout"], "description": p["description"], "legs": entries, "id": p["id"],
                      "live": any(e.get("in_play") for e in entries) and p["status"] == "open", "status": p["status"],
                      "net": pick_net(p), "sport": p["sport"], "show": design_enrich(p, entries)})
    if not slips:
        return None
    slips.sort(key=lambda s: (s["status"] != "open", not s["live"],
                              -sum(1 for e in s["legs"] if leg_visual(e)["state"] in ("hit", "ahead"))))
    all_legs = [e for s in slips for e in s["legs"]]
    live = any(s["live"] for s in slips)
    data = {"title": "TONIGHT'S BOARD", "when": datetime.now(TZ).strftime("%a %b %-d · %-I:%M %p"), "live": live,
            "slips": slips, "totals": {"slips": len(slips), "cost": sum(s["cost"] for s in slips if s["status"] == "open"),
                                       "payout": sum(s["payout"] for s in slips if s["status"] == "open"),
                                       "legs": len(all_legs),
                                       "cashing": sum(1 for e in all_legs if leg_visual(e)["state"] in ("hit", "ahead"))}}
    sig = json.dumps([[s["id"], receipt_sig({"status": s["status"]}, s["legs"])] for s in slips])
    memo = _DESIGN_BOARD_MEMO.get(guild_id)
    if memo and memo[0] == sig and memo[2] > time.monotonic():
        return io.BytesIO(memo[1]), live, sig, len(slips)
    data["art"] = await design_fetch_art([e for s in slips for e in s["show"]])
    png = await asyncio.to_thread(locked_render, render_board, data)
    _DESIGN_BOARD_MEMO[guild_id] = (sig, png.getvalue(), time.monotonic() + DESIGN_BOARD_MEMO_S)
    return png, live, sig, len(slips)


class BoardButton(discord.ui.DynamicItem[discord.ui.Button], template=r"bd:(?P<act>ref|stop)"):
    def __init__(self, act: str):
        label = {"ref": "🔄 Refresh", "stop": "🛑 Stop"}[act]
        super().__init__(discord.ui.Button(label=label, style=discord.ButtonStyle.secondary, custom_id=f"bd:{act}"))
        self.act = act

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["act"])

    async def callback(self, interaction: discord.Interaction):
        st = board_state(interaction.guild_id)
        current = bool(st) and getattr(interaction.message, "id", None) == st.get("message_id")
        if not current:
            await interaction.response.edit_message(view=None)   # an old board: retire its buttons
            return
        if self.act == "stop":
            if interaction.user.id != st.get("by") and not is_mod(interaction.user):
                await interaction.response.send_message("Only whoever started the board or a mod can stop it.",
                                                        ephemeral=True)
                return
            set_setting(interaction.guild_id, "board", None)
            await interaction.response.edit_message(view=None)
            return
        if await sec_button_slow(interaction, "board_refresh"):
            return
        await interaction.response.defer()
        snap = await board_snapshot(interaction.client, interaction.guild_id)
        if snap is None:
            await interaction.followup.send("No open slips with games today.", ephemeral=True)
            return
        png, live, sig, _ = snap
        if st:
            st["sig"] = sig
            set_setting(interaction.guild_id, "board", json.dumps(st))
        await interaction.edit_original_response(attachments=[discord.File(png, filename="board.png")], view=board_view())


def board_view() -> discord.ui.View:
    v = discord.ui.View(timeout=None)
    v.add_item(BoardButton("ref"))
    v.add_item(BoardButton("stop"))
    return v


async def retire_board(client, guild_id: int) -> None:
    st = board_state(guild_id)
    if not st:
        return
    set_setting(guild_id, "board", None)
    channel = client.get_channel(st["channel_id"]) if client is not None else None
    if channel is not None:
        try:
            await channel.get_partial_message(st["message_id"]).edit(view=None)
        except Exception:
            pass


async def start_board(client, guild_id: int, channel, by: int = 0) -> bool:
    snap = await board_snapshot(client, guild_id)
    if snap is None:
        return False
    await retire_board(client, guild_id)
    png, live, sig, _ = snap
    msg = await channel.send(file=discord.File(png, filename="board.png"), view=board_view())
    set_setting(guild_id, "board", json.dumps({"channel_id": channel.id, "message_id": msg.id, "started": now_iso(),
                                               "sig": sig, "by": by}))
    return True


async def update_boards(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    for r in db().execute("SELECT guild_id, value FROM settings WHERE key = 'board' AND value IS NOT NULL").fetchall():
        gid = r["guild_id"]
        try:
            st = json.loads(r["value"])
            channel = client.get_channel(st["channel_id"])
            if channel is None:
                channel = await _alert_channel(client, st["channel_id"])
            if channel is None:
                continue
            expired = datetime.fromisoformat(st["started"]) < now - timedelta(hours=BOARD_HOURS)
            snap = None if expired else await board_snapshot(client, gid)
            msg = channel.get_partial_message(st["message_id"])
            if snap is None:
                set_setting(gid, "board", None)
                await msg.edit(view=None)
                continue
            png, live, sig, _ = snap
            if sig != st.get("sig"):
                st["sig"] = sig
                set_setting(gid, "board", json.dumps(st))
                await msg.edit(attachments=[discord.File(png, filename="board.png")])
        except discord.NotFound:
            set_setting(gid, "board", None)
        except Exception:
            log.warning("Board update failed for guild %s", gid, exc_info=True)
    # auto mode: post one when two or more slips have games going and nothing is up yet today
    today = now.astimezone(TZ).date().isoformat()
    for r in db().execute("SELECT guild_id FROM settings WHERE key = 'board_auto' AND value = 'on'").fetchall():
        gid = r["guild_id"]
        try:
            if board_state(gid) or get_setting(gid, "board_auto_day") == today:
                continue
            channel = await recap_channel_for(client, gid)
            if channel is None:
                continue
            snap = await board_snapshot(client, gid)
            if snap and snap[1] and snap[3] >= 2:
                set_setting(gid, "board_auto_day", today)
                await start_board(client, gid, channel)
        except Exception:
            log.warning("Auto board failed for guild %s", gid, exc_info=True)


# ---- the Sunday Show -----------------------------------------------------------------------------------

SHOW_SYSTEM = """You are the host of "The Sunday Show", the weekly recap for a Discord group of friends who \
track their sports picks (PrizePicks, Kalshi, sportsbooks). Voice: {voice}.
Write the show from the data below, in Discord markdown, 180-300 words, with these bolded segments in order, \
skipping any with no data: **🎬 Top story**, **🔥 Heating up**, **🧊 Ice cold**, **🎯 Play of the week**, \
**💔 Bad beat of the week**, **👀 Next week**. Use names exactly as given. Every number must come from the data. \
Never mention odds, prices or line movement, and never push anyone to bet more, chase losses or raise stakes. \
Keep teasing about the bets, never personal."""


def show_data(guild_id: int, now: Optional[datetime] = None) -> dict:
    now = now or datetime.now(timezone.utc)
    since = iso(now - timedelta(days=7))
    week = compute_stats(guild_id, since=since)
    season = compute_stats(guild_id)
    picks = db().execute("SELECT * FROM picks WHERE guild_id = ? AND status != 'open' AND settled_at >= ? AND "
                         "(hidden IS NULL OR hidden = 0 OR revealed_at IS NOT NULL)", (guild_id, since)).fetchall()
    wins = [p for p in picks if p["status"] == "win"]
    best = max(wins, key=pick_net) if wins else None
    beats = []
    for p in picks:
        if p["status"] == "loss":
            legs = get_legs(p["id"])
            if len(legs) >= 3 and sum(1 for x in legs if x["status"] == "miss") == 1:
                beats.append((p, next(x["text"] for x in legs if x["status"] == "miss")))
    beat = max(beats, key=lambda b: b[0]["payout"]) if beats else None
    streaks = []
    for s in season:
        st = current_streak(guild_id, s["key"]).lstrip("🔥🧊")
        if st:
            streaks.append({"name": s["name"], "streak": st})
    open_n = db().execute("SELECT COUNT(*) AS n FROM picks WHERE guild_id = ? AND status = 'open'", (guild_id,)).fetchone()["n"]
    return {
        "week": [{"name": s["name"], "record": record_line(s), "net": round(s["net"], 2), "roi_pct": round(s["roi"], 1)}
                 for s in week],
        "group_week_net": round(sum(s["net"] for s in week), 2),
        "season_top3": [{"name": s["name"], "net": round(s["net"], 2), "record": record_line(s)} for s in season[:3]],
        "play_of_week": {"name": best["bettor_name"], "description": best["description"], "net": round(pick_net(best), 2),
                         "mult": round((best["returned"] or 0) / best["cost"], 1) if best["cost"] else None,
                         "pick_id": best["id"]} if best else None,
        "bad_beat": {"name": beat[0]["bettor_name"], "description": beat[0]["description"], "missed_leg": beat[1],
                     "would_have_paid": beat[0]["payout"]} if beat else None,
        "streaks": streaks[:8], "open_picks": open_n,
    }


def show_fallback(d: dict) -> str:
    parts = []
    if d["week"]:
        top = d["week"][0]
        parts.append(f"**🎬 Top story**\n{top['name']} ran the week at {top['record']}, {signed(top['net'])}. "
                     f"The group finished {signed(d['group_week_net'])}.")
        hot = [w for w in d["week"] if w["net"] > 0][:3]
        if hot:
            parts.append("**🔥 Heating up**\n" + ", ".join(f"{w['name']} ({signed(w['net'])})" for w in hot))
        cold = [w for w in d["week"] if w["net"] < 0][-2:]
        if cold:
            parts.append("**🧊 Ice cold**\n" + ", ".join(f"{w['name']} ({signed(w['net'])})" for w in cold))
    if d["play_of_week"]:
        pw = d["play_of_week"]
        parts.append(f"**🎯 Play of the week**\n{pw['name']}: {signed(pw['net'])} on {pw['description']}.")
    if d["bad_beat"]:
        bb = d["bad_beat"]
        parts.append(f"**💔 Bad beat of the week**\n{bb['name']} lost {bb['description']} by one leg: {bb['missed_leg']}.")
    parts.append(f"**👀 Next week**\n{d['open_picks']} picks still riding. See you next Sunday.")
    return "\n\n".join(parts)


async def write_show(guild_id: int, d: dict) -> str:
    if not ai_enabled() or not d["week"] or not claude_budget_ok():
        return show_fallback(d)
    try:
        reply = await asyncio.wait_for(anthropic_client().messages.create(
            model=ASK_MODEL, max_tokens=1200, system=SHOW_SYSTEM.format(voice=persona_prompt(guild_id)),
            messages=[{"role": "user", "content": "This week's data:\n" + json.dumps(d, indent=1)}]), timeout=60)
        text = "".join(b.text for b in reply.content if getattr(b, "type", "") == "text").strip()
        return text or show_fallback(d)
    except Exception:
        log.warning("Sunday Show writing failed; using the template", exc_info=True)
        return show_fallback(d)


def show_embed(text: str, now: Optional[datetime] = None) -> discord.Embed:
    now = (now or datetime.now(timezone.utc)).astimezone(TZ)
    e = discord.Embed(title="📺 The Sunday Show", description=clip(text, 4000), color=BRAND)
    e.set_footer(text=f"Week ending {now:%b %-d} · PIMP-BOT")
    return e


async def post_show(client, guild_id: int, channel, now: Optional[datetime] = None) -> None:
    d = show_data(guild_id, now)
    text = await write_show(guild_id, d)
    e = show_embed(text, now)
    kwargs = {}
    if d["play_of_week"]:
        p = get_pick(guild_id, d["play_of_week"]["pick_id"])
        if p is not None:
            f = await receipt_file(client, p, db_entries(p))
            e.set_image(url=f"attachment://{f.filename}")
            kwargs["file"] = f
    await channel.send(embed=e, allowed_mentions=discord.AllowedMentions.none(), **kwargs)
    posters = []
    for make in (lambda: cashed_poster_file(client, guild_id), lambda: standings_poster_file(client, guild_id)):
        try:
            f = await make()
            if f is not None:
                posters.append(f)
        except Exception:
            log.warning("Poster failed", exc_info=True)
    if posters:
        await channel.send(files=posters, allowed_mentions=discord.AllowedMentions.none())
    await voice_say(client, guild_id, "The Sunday Show is up. " + re.sub(r"[*_`#>]|<[^>]+>", "", text.split("\n\n")[0])[:240])


# ---- voice ------------------------------------------------------------------------------------------------

VOICE: dict[int, dict] = {}
GREETINGS = {"default": "PIMP-BOT is in the building. Let's sweat.",
             "hype": "LET'S GOOO! PIMP-BOT IS IN THE BUILDING! Who's cashing tonight?",
             "analyst": "PIMP-BOT connected. Monitoring open positions.",
             "trash": "Alright, I'm here. Try not to embarrass yourselves.",
             "announcer": "Good evening and welcome to tonight's sweat, brought to you by PIMP-BOT!"}
VOICE_MAX_HOURS = 8


def voice_ready() -> tuple[bool, str]:
    """Whether this install can talk in voice, and what's missing if not."""
    try:
        import nacl  # noqa: F401
    except Exception:
        return False, "PyNaCl isn't installed (it comes with `discord.py[voice]` in requirements.txt)"
    try:
        import davey  # noqa: F401
    except Exception:
        return False, "the `davey` package isn't installed (Discord's encrypted voice needs it)"
    import shutil
    if not shutil.which("ffmpeg"):
        return False, "ffmpeg isn't installed (the included Dockerfile installs it)"
    try:
        if not discord.opus.is_loaded():
            discord.opus._load_default()
    except Exception:
        pass
    try:
        if not discord.opus.is_loaded():
            return False, "the opus audio library isn't installed (the included Dockerfile installs libopus0)"
    except Exception:
        pass
    return True, ""


def tts_to_file(text: str) -> str:
    """Speak text into a temp audio file: Google TTS (free), or espeak-ng if that's unavailable.
    The caller deletes the file's folder."""
    folder = tempfile.mkdtemp()
    try:
        from gtts import gTTS
        path = os.path.join(folder, "say.mp3")
        gTTS(text=text, lang="en", tld="us").save(path)
        return path
    except Exception:
        import shutil
        import subprocess
        exe = shutil.which("espeak-ng") or shutil.which("espeak")
        if not exe:
            import shutil as _sh
            _sh.rmtree(folder, ignore_errors=True)
            raise RuntimeError("no text-to-speech available (install gTTS or espeak-ng)")
        path = os.path.join(folder, "say.wav")
        subprocess.run([exe, "-s", "165", "-w", path, text.lstrip("- ") or "."], check=True, timeout=30)
        return path


def speakable(text: str) -> str:
    t = re.sub(r"<a?:\w+:\d+>|<[@#&!]+\d+>|https?://\S+", "", text)
    t = re.sub(r"[*_`~>|#]", "", t)
    t = re.sub(r"[\U0001F000-\U0001FAFF☀-➿️]", "", t)
    t = re.sub(r"\$([\d,]+)(?:\.00\b)?(\.\d\d)?", lambda m: f"{m.group(1)}{m.group(2) or ''} dollars", t)
    t = t.replace("→", " to ").replace("$", "")
    return " ".join(t.split())[:300]


async def _voice_worker(gid: int):
    st = VOICE.get(gid)
    while st is not None:
        text = await st["queue"].get()
        vc = st["vc"]
        for _ in range(10):   # ride out a voice reconnect instead of going silent for good
            if vc and vc.is_connected():
                break
            await asyncio.sleep(3)
        if not vc or not vc.is_connected():
            st = VOICE.get(gid)
            continue
        path = None
        try:
            path = await asyncio.to_thread(tts_to_file, text)
            done = asyncio.Event()
            loop = asyncio.get_running_loop()
            vc.play(discord.FFmpegPCMAudio(path), after=lambda e: loop.call_soon_threadsafe(done.set))
            try:
                await asyncio.wait_for(done.wait(), timeout=90)
            except asyncio.TimeoutError:
                vc.stop()
        except Exception:
            log.warning("Voice line failed", exc_info=True)
        finally:
            if path:
                import shutil
                shutil.rmtree(os.path.dirname(path), ignore_errors=True)
        st["last"] = time.monotonic()
        st = VOICE.get(gid)


async def voice_join(guild_id: int, channel) -> str:
    ok, why = voice_ready()
    if not ok:
        return f"I can't talk in voice on this install: {why}."
    st = VOICE.get(guild_id)
    try:
        if st and st["vc"].is_connected():
            await st["vc"].move_to(channel)
        else:
            vc = await channel.connect(self_deaf=True)
            st = {"vc": vc, "queue": asyncio.Queue(), "joined": time.monotonic(), "last": time.monotonic()}
            VOICE[guild_id] = st
            st["task"] = asyncio.create_task(_voice_worker(guild_id))
    except Exception as exc:
        log.exception("Voice connect failed")
        return f"I couldn't join voice ({type(exc).__name__}). Check I can Connect and Speak in that channel."
    return ""


async def voice_leave(guild_id: int) -> bool:
    st = VOICE.pop(guild_id, None)
    if not st:
        return False
    try:
        if st.get("task"):
            st["task"].cancel()
        await st["vc"].disconnect(force=True)
    except Exception:
        pass
    return True


async def voice_say(client, guild_id: int, text: str) -> bool:
    st = VOICE.get(guild_id)
    if not st or not st["vc"] or not st["vc"].is_connected():
        return False
    line = speakable(text)
    if not line:
        return False
    if st.get("task") is None or st["task"].done():
        st["task"] = asyncio.create_task(_voice_worker(guild_id))
    if st["queue"].qsize() < 6:
        st["queue"].put_nowait(line)
    return True


async def voice_idle(client: discord.Client, now: Optional[datetime] = None) -> None:
    for gid, st in list(VOICE.items()):
        vc = st["vc"]
        humans = [m for m in getattr(getattr(vc, "channel", None), "members", []) if not getattr(m, "bot", False)]
        if humans:
            st.pop("empty_since", None)
        else:
            st.setdefault("empty_since", time.monotonic())
        if (not vc.is_connected() or time.monotonic() - st.get("empty_since", time.monotonic()) > 300
                or time.monotonic() - st["joined"] > VOICE_MAX_HOURS * 3600):
            await voice_leave(gid)


# ==========================================================================
# r15: slip X-ray, ghost slips, leg-by-leg DMs, sweat radio, quiet hours
# ==========================================================================

# ---- nightly cleanup -----------------------------------------------------------------------------

def cleanup_db(now: Optional[datetime] = None, vacuum: bool = False) -> dict:
    """Drop the bot's own scratch data once it can't matter any more. Never touches picks, legs or money."""
    now = now or datetime.now(timezone.utc)
    week, month = iso(now - timedelta(days=7)), iso(now - timedelta(days=30))
    removed: dict[str, int] = {}
    # slip drafts (screenshots asked about or not placed) older than a week
    n = 0
    for r in db().execute("SELECT guild_id, key, value FROM settings WHERE key LIKE 'draft:%'").fetchall():
        try:
            d = json.loads(r["value"] or "{}")
        except ValueError:
            d = {}
        if not d.get("at"):
            d["at"] = now_iso()     # older drafts had no date: start their clock now
            db().execute("UPDATE settings SET value = ? WHERE guild_id = ? AND key = ?",
                         (json.dumps(d), r["guild_id"], r["key"]))
        elif d["at"] < week:
            db().execute("DELETE FROM settings WHERE guild_id = ? AND key = ?", (r["guild_id"], r["key"]))
            n += 1
    removed["slip drafts"] = n
    # daily question counters from more than a week ago
    cutoff_day = (now.astimezone(TZ) - timedelta(days=7)).date().isoformat()
    removed["old question counters"] = db().execute(
        "DELETE FROM settings WHERE key LIKE 'asks:%' AND substr(key, 6) < ?", (cutoff_day,)).rowcount
    r15_db()
    r14_db()
    removed["expired ghost slips"] = db().execute(
        "DELETE FROM ghosts WHERE result = 'expired' AND settled_at < ?", (month,)).rowcount
    removed["leg alert marks"] = db().execute(
        "DELETE FROM leg_pings WHERE pick_id IN (SELECT id FROM picks WHERE status != 'open' AND settled_at < ?)",
        (week,)).rowcount
    removed["finished receipt trackers"] = db().execute(
        "DELETE FROM pick_msgs WHERE done = 1 AND updated_at < ?", (month,)).rowcount
    removed["leg alert marks"] += db().execute(
        "DELETE FROM leg_pings WHERE pick_id NOT IN (SELECT id FROM picks)").rowcount
    cutoff_reads = (now.astimezone(TZ) - timedelta(days=21)).date().isoformat()
    removed["old scan counters"] = db().execute(
        "DELETE FROM settings WHERE key LIKE 'slipreads:%' AND substr(key, 11) < ?", (cutoff_reads,)).rowcount
    db().commit()
    try:
        db().execute("PRAGMA optimize")
        db().execute("PRAGMA wal_checkpoint(TRUNCATE)")
        if vacuum:
            free, _, db_n = disk_bytes()
            if free and db_n and free < db_n * 2 + 100 * 1024 * 1024:
                log.warning("Skipping database compact: %s MB free, database %s MB",
                            free // (1024 * 1024), db_n // (1024 * 1024))
            else:
                db().execute("VACUUM")
    except Exception:
        log.warning("Database optimize/vacuum skipped", exc_info=True)
    total = sum(removed.values())
    set_setting(0, "cleanup_last", json.dumps({"at": now_iso(), "removed": total,
                                               "detail": {k: v for k, v in removed.items() if v}}))
    return removed


async def nightly_cleanup(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    local = now.astimezone(TZ)
    today = local.date().isoformat()
    if local.hour < (BACKUP_HOUR + 1) % 24 or get_setting(0, "cleanup_day") == today:
        return
    set_setting(0, "cleanup_day", today)
    swept = sweep_storage()
    removed = cleanup_db(now, vacuum=local.weekday() == 6)
    log.info("Nightly cleanup removed %s; swept %s leftover backup folders", removed, swept)
    try:
        await storage_alert(client)
    except Exception:
        log.warning("Storage alert failed", exc_info=True)
    for cache in (_PROP_CACHE, _PROGRESS_CACHE, _AVATAR_CACHE, _LEG_SEEN):
        if len(cache) > 1000:
            cache.clear()


# ---- quiet hours -----------------------------------------------------------------------------

class QuietHours(Exception):
    """Raised inside a DM's try block to skip it quietly."""


def quiet_window(guild_id: int, user_id) -> Optional[tuple[int, int]]:
    raw = get_setting(guild_id, f"quiet:{user_id}") or get_setting(0, f"quiet:{user_id}")
    if not raw:
        return None
    try:
        a, b = (int(x) for x in raw.split("-"))
        return a, b
    except ValueError:
        return None


def is_quiet(guild_id: int, user_id, now: Optional[datetime] = None) -> bool:
    w = quiet_window(guild_id, user_id)
    if not w:
        return False
    h = (now or datetime.now(TZ)).astimezone(TZ).hour
    a, b = w
    return (a <= h < b) if a < b else (h >= a or h < b)


def hour_label(h: int) -> str:
    return datetime(2026, 1, 1, h).strftime("%-I %p").lower()


# ---- slip X-ray --------------------------------------------------------------------------------

def _log_copy(games: list) -> list:
    return [{**g, "groups": {k: dict(v or {}) for k, v in (g.get("groups") or {}).items()}} for g in (games or [])]


def _filled_n(games: list, stat: str) -> int:
    if not stat or stat not in STATS:
        return 0
    return len(trend_values([g for g in games if not g.get("preseason")], stat))


def _pull_choice(c: dict, stat: str) -> dict:
    team = c.get("team") or c.get("team_abbr") or ""
    pos = c.get("position") or c.get("pos") or ""
    label = " · ".join(x for x in (c.get("name") or "", team, STATS.get(stat, ("",))[0]) if x)
    return {"id": str(c.get("id") or ""), "name": c.get("name") or "", "team": team, "pos": pos,
            "path": c.get("path") or "", "stat": stat, "label": label[:80]}


def xref_mlb_game(split: dict, kind: str) -> Optional[dict]:
    """One MLB Stats API gameLog split, shaped like an ESPN game so the usual stat reader can use it."""
    stat = split.get("stat") or {}
    if not isinstance(stat, dict) or not stat:
        return None
    opp = split.get("opponent") or {}
    name = opp.get("abbreviation") or opp.get("name") or "?"
    if " " in str(name):
        name = str(name).split()[-1]
    groups: dict = {}
    if kind == "hitting":
        bat = {}
        for src, dst in (("hits", "hits"), ("runs", "runs"), ("rbi", "rbis"), ("homeRuns", "homeruns"),
                         ("baseOnBalls", "walks"), ("strikeOuts", "strikeouts")):
            if isinstance(stat.get(src), (int, float)):
                bat[dst] = str(stat[src])
        if bat:
            groups["batting"] = bat
    else:
        pit = {}
        for src, dst in (("strikeOuts", "strikeouts"), ("hits", "hits"), ("earnedRuns", "earnedruns"),
                         ("baseOnBalls", "walks")):
            if isinstance(stat.get(src), (int, float)):
                pit[dst] = str(stat[src])
        ip = stat.get("inningsPitched")
        if ip is not None:
            pit["innings"] = str(ip)
        if pit:
            groups["pitching"] = pit
    if not groups:
        return None
    day = str(split.get("date") or "")
    return {"id": f"mlb-{day}-{name}", "date": day, "opp": str(name)[:8],
            "at": "vs" if split.get("isHome") else "@", "result": "", "label": "MLB Stats API",
            "preseason": False, "groups": groups, "xref": "MLB Stats API"}


def xref_nhl_game(row: dict) -> Optional[dict]:
    """One NHL.com game-log row, shaped like an ESPN game."""
    if not isinstance(row, dict):
        return None
    main = {}
    for src, dst in (("goals", "goals"), ("assists", "assists"), ("shots", "shotstotal"),
                     ("hits", "hits"), ("blockedShots", "blockedshots"), ("saves", "saves")):
        if isinstance(row.get(src), (int, float)):
            main[dst] = str(row[src])
    if not main:
        return None
    groups = {"main": {k: v for k, v in main.items() if k != "saves"}}
    if "saves" in main:
        groups["goalies"] = {"saves": main["saves"]}
    opp = str(row.get("opponentAbbrev") or "?")[:8]
    day = str(row.get("gameDate") or "")
    return {"id": f"nhl-{row.get('gameId') or day}-{opp}", "date": day, "opp": opp,
            "at": "vs" if str(row.get("homeRoadFlag") or "").upper() == "H" else "@",
            "result": "", "label": "NHL.com", "preseason": False, "groups": groups, "xref": "NHL.com"}


def _mlb_season_year(now: Optional[datetime] = None) -> int:
    now = now or datetime.now(TZ)
    return now.year if now.month >= 3 else now.year - 1


def _nhl_season_ids(now: Optional[datetime] = None) -> list[str]:
    now = now or datetime.now(TZ)
    y = now.year if now.month >= 9 else now.year - 1
    return [f"{y}{y + 1}", f"{y - 1}{y}"]


_PITCH_STATS = {"pitcher_k", "pitching_outs", "earned_runs", "hits_allowed", "walks_allowed"}


async def xref_box_fill(path: str, athlete_id: str, name: str, games: list, stat: str, limit: int = 4) -> tuple[list, int]:
    """Copy box-score columns into games whose log is missing this stat. The cached log is left alone."""
    games = _log_copy(games)
    if not stat or stat not in STATS:
        return games, 0
    need = []
    for g in games:
        if g.get("preseason") or not g.get("id") or str(g.get("id")).startswith(("mlb-", "nhl-")):
            continue
        try:
            missing = stat_value(g.get("groups") or {}, stat) is None
        except Exception:
            missing = True
        if missing:
            need.append(g)
        if len(need) >= limit:
            break
    if not need:
        return games, 0

    async def one(g):
        try:
            box = await asyncio.wait_for(fetch_summary(path, str(g["id"])), 2.5)
        except Exception:
            box = None
        return g, box

    n, target = 0, norm_name(name or "")
    for g, box in await asyncio.gather(*(one(g) for g in need)):
        if not box:
            continue
        pl = None
        for p in box.get("players") or []:
            if str(p.get("id") or "") == str(athlete_id) or (target and name_score(target, p.get("norm") or "") >= 2):
                pl = p
                break
        if not pl or not pl.get("groups"):
            continue
        groups = g.setdefault("groups", {})
        for gk, vals in pl["groups"].items():
            slot = groups.setdefault(gk, {})
            for k, v in (vals or {}).items():
                slot.setdefault(k, v)
        try:
            got = stat_value(groups, stat) is not None
        except Exception:
            got = False
        if got:
            n += 1
            g["xref"] = "ESPN box score"
    return games, n


async def xref_official(name: str, path: str, stat: str) -> tuple[list, str]:
    """The league's own game log for this name. Empty when that feed has nothing, or this sport has no second feed."""
    name = (name or "").strip()
    if len(name) < 3 or path not in ("baseball/mlb", "hockey/nhl"):
        return [], ""
    try:
        if path == "baseball/mlb":
            found = await _alt_get(f"{MLB_API}/people/search", {"names": name, "sportId": 1}, 6 * 3600)
            people = (found or {}).get("people") if isinstance(found, dict) else []
            best, pid = 0, None
            for p in people or []:
                sc = name_score(norm_name(name), norm_name(p.get("fullName") or ""))
                if sc > best and p.get("id"):
                    best, pid = sc, p["id"]
            if not pid or best < 2:
                return [], ""
            kind = "pitching" if stat in _PITCH_STATS else "hitting"
            year = _mlb_season_year()
            raw = await _alt_get(
                f"{MLB_API}/people/{pid}",
                {"hydrate": f"stats(group=[{kind}],type=[gameLog],season={year})"}, 1800)
            person = ((raw or {}).get("people") or [{}])[0] if isinstance(raw, dict) else {}
            games = []
            for block in person.get("stats") or []:
                for split in block.get("splits") or []:
                    g = xref_mlb_game(split, kind)
                    if g:
                        games.append(g)
            games.sort(key=lambda g: g.get("date") or "", reverse=True)
            return games[:30], "MLB Stats API"
        rows = await _alt_get("https://search.d3.nhle.com/api/v1/search/player",
                              {"culture": "en-us", "limit": 6, "q": name}, 6 * 3600)
        if isinstance(rows, dict):
            rows = rows.get("results") or rows.get("players") or []
        best, pid = 0, None
        for p in rows or []:
            if not isinstance(p, dict):
                continue
            sc = name_score(norm_name(name), norm_name(p.get("name") or ""))
            if p.get("active") is False:
                sc = min(sc, 1)
            if sc > best and p.get("playerId"):
                best, pid = sc, p["playerId"]
        if not pid or best < 2:
            return [], ""
        games = []
        for season in _nhl_season_ids():
            raw = await _alt_get(f"{NHL_WEB}/player/{pid}/game-log/{season}/2", {}, 1800)
            for row in ((raw or {}).get("gameLog") or []) if isinstance(raw, dict) else []:
                g = xref_nhl_game(row)
                if g:
                    games.append(g)
            if _filled_n(games, stat) >= 4:
                break
        return games[:30], "NHL.com"
    except Exception:
        log.debug("League log failed for %s", name, exc_info=True)
        return [], ""


async def deepen_games(path: str, athlete_id: str, name: str, stat: str, games: list, *, fast: bool = False) -> tuple[list, str]:
    """ESPN's log first. When that stat is thin, fill from the box score, then the league's own feed."""
    games = list(games or [])
    sources = ["ESPN game log"] if games else []
    n0 = _filled_n(games, stat)
    if stat and n0 < 4 and games:
        try:
            filled, n = await xref_box_fill(path, str(athlete_id), name, games, stat, 3 if fast else 6)
        except Exception:
            log.debug("Box fill failed", exc_info=True)
            filled, n = games, 0
        if n:
            games, n0 = filled, _filled_n(filled, stat)
            sources.append("ESPN box score")
    if stat and n0 < 4 and path in ("baseball/mlb", "hockey/nhl"):
        try:
            official, label = await asyncio.wait_for(xref_official(name, path, stat), 2.5 if fast else 6)
        except Exception:
            official, label = [], ""
        if label and _filled_n(official, stat) > n0:
            games = official
            sources.append(label)
    return games, " · ".join(sources)


async def _xray_one(player: str, stats: list, sport: Optional[str], *, fast: bool = True):
    """One player's newest games for the first stat that resolves, or why it didn't.
    A name that fits several people comes back with those people instead of a guess."""
    sport_paths = [p for p in leagues_for(sport) if p in PROP_PATHS] if sport else []
    cand, stat, ambiguous, pool = None, None, False, []
    for key in stats:
        fam = STATS[key][1]
        paths = [p for p in PROP_PATHS if FAMILY_OF_PATH[p] == fam]
        narrowed = [p for p in paths if p in sport_paths]
        # A mixed slip (MLB + WNBA + NBAP) must not hide an NBA player just because WNBA was also on the screenshot.
        cands = fit_position(await resolve_player(player, narrowed), key) if narrowed else []
        if len(cands) != 1:
            wider = fit_position(await resolve_player(player, paths), key)
            if len(wider) == 1 or not cands:
                cands = wider
        if len(cands) == 1:
            cand, stat = cands[0], key
            break
        if len(cands) > 1 and not pool:
            ambiguous, pool, stat = True, cands, key
    if cand is None:
        why = "more than one player by that name" if ambiguous else "no ESPN game log for this player"
        choices = [_pull_choice(c, stat) for c in pool[:6]] if stat else []
        return None, stat, [], why, choices, ""
    games = await trend_games(cand["path"], cand["id"], need=10)
    if _filled_n(games, stat) < 4:
        games, src = await deepen_games(cand["path"], cand["id"], cand.get("name") or player, stat, games, fast=fast)
    else:
        src = "ESPN game log"
    values = trend_values(games, stat)[:10]
    return cand, stat, values, "", [], src


def _pair_combo(a: list, b: list) -> list:
    """Add two newest-first logs. Same game when they share one; otherwise the same slot in each last 10."""
    b_by = {}
    for g, v in b:
        gid = str(g.get("id") or "")
        if gid:
            b_by.setdefault(gid, v)
    shared = []
    for g, v in a:
        gid = str(g.get("id") or "")
        if gid and gid in b_by:
            shared.append((g, round(v + b_by[gid], 2)))
    if len(shared) >= 4:
        return shared[:10]
    out = []
    for i in range(min(len(a), len(b), 10)):
        g = dict(a[i][0])
        g["opp"] = "A+B"
        out.append((g, round(a[i][1] + b[i][1], 2)))
    return out


async def xray_leg(leg_text: str, sport: Optional[str] = None, alts: Optional[list] = None) -> dict:
    """The player's last 10 games against this leg's number, or why there isn't a chart."""
    out = {"text": leg_text, "values": [], "line": None, "side": None, "name": None, "stat": None, "why": ""}
    pr = cached_prop(leg_text)
    if not pr:
        out["why"] = "not a player prop"
        return out
    side = pr["side"] if not pr.get("negate") else ("under" if pr["side"] == "over" else "over")
    out.update(line=pr["line"], side=side, name=pr["display"])
    if pr.get("combo"):
        series, names, stat = [], [], None
        for part in pr["combo"]:
            cand, stat, values, why, choices, src = await _xray_one(part["player"], part.get("stats") or pr["stats"], sport)
            if cand is None:
                out["why"] = why
                out["choices"] = choices
                out["stat_key"] = stat or ""
                return out
            names.append(cand["name"])
            series.append(values)
            out["path"] = cand["path"]
        paired = _pair_combo(series[0], series[1]) if len(series) == 2 else []
        label = STATS[stat][0] if stat else ""
        out.update(name=" + ".join(names), stat=label,
                   values=[(g["opp"], g["at"], v) for g, v in paired][::-1])
        if not paired:
            out["why"] = f"no {label} in recent games"
        return out
    cand, stat, values, why, choices, src = await _xray_one(pr["player"], pr["stats"], sport)
    if cand is None and alts:
        for alt in alts:
            if norm_name(alt) == norm_name(pr["player"]):
                continue
            cand, stat, values, why, choices, src = await _xray_one(alt, pr["stats"], sport)
            if cand is not None or choices:
                break
    if cand is None:
        out["why"] = why
        out["choices"] = choices
        out["stat_key"] = stat or ""
        return out
    out.update(name=cand["name"], stat=STATS[stat][0], stat_key=stat, sources=src,
               values=[(g["opp"], g["at"], v) for g, v in values][::-1],
               path=cand["path"])
    if not values:
        out["why"] = f"no {STATS[stat][0]} in recent games"
    return out


async def slip_xray_data(slip: dict) -> list[dict]:
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()][:8]
    alts = slip.get("_name_alts") if isinstance(slip.get("_name_alts"), dict) else {}

    def extras(t: str) -> list:
        out = []
        low = t.lower()
        for raw, names in alts.items():
            if raw and str(raw).lower() in low and isinstance(names, list):
                out.extend(str(n) for n in names if n)
        return out[:4]

    async def one(t):
        try:
            return await asyncio.wait_for(xray_leg(t, slip.get("sport"), extras(t)), timeout=6)
        except Exception:
            log.warning("X-ray failed for %r", t, exc_info=True)
            return {"text": t, "values": [], "line": None, "side": None, "name": None, "stat": None,
                    "why": "couldn't load the game log"}
    return list(await asyncio.gather(*(one(t) for t in legs)))


def xray_hits(x: dict) -> Optional[tuple[int, int]]:
    if not x["values"] or x["line"] is None:
        return None
    vals = [v for _, _, v in x["values"]]
    good = sum(1 for v in vals if (v > x["line"] if x["side"] == "over" else v < x["line"]))
    return good, len(vals)


def line_suspect(x: dict) -> bool:
    """True when the line can't be what was on the slip: far below or above everything the player does."""
    vals = [v for _, _, v in (x.get("values") or [])]
    line = x.get("line")
    if not vals or line is None or line <= 0 or len(vals) < 3:
        return False
    avg, top = sum(vals) / len(vals), max(vals)
    if line > 3 * top + 1:
        return True                                     # Kyren "over 23" TDs when he's never had more than 2
    return line >= 1 and avg >= 8 * line and min(vals) > line and avg >= 15   # 4.6 against 90-yard games


def xray_notes(data: list[dict]) -> list[str]:
    notes = []
    for x in data:
        h = xray_hits(x)
        if h and line_suspect(x):
            vals = [v for _, _, v in x["values"]]
            notes.append(f"- {x['text']}: THIS LINE LOOKS MISREAD from the screenshot (avg {sum(vals) / len(vals):.1f} "
                         f"against a line of {x['line']:g}). Say the line looks wrong and to check the slip; don't rate it.")
            continue
        if h:
            vals = [v for _, _, v in x["values"]]
            src = f" · {x['sources']}" if x.get("sources") and x.get("sources") != "ESPN game log" else ""
            notes.append(f"- {x['text']}: last {h[1]} games {h[0]}/{h[1]} {x['side']} {x['line']:g} "
                         f"(avg {sum(vals) / len(vals):.1f}, most recent {', '.join(f'{v:g}' for v in vals[-5:][::-1])}){src}")
    return notes


def render_xray(title: str, data: list[dict], heading: str = "SLIP X-RAY",
                sport: Optional[str] = None) -> io.BytesIO:
    from PIL import Image, ImageDraw
    W, ROW, SHORT = 1000, 190, 96
    H = 120 + sum(ROW if xray_hits(x) else SHORT for x in data) + 50
    img, d = _design_card(W, H, design_sport_key(sport, *(x.get("stat") or x.get("text") for x in data)),
                          (70, 34, 150), head=150, margin=0, radius=0)
    d.text((36, 26), heading, font=art_font(40, True), fill=ART_TEXT)
    t, f = fit_text(d, title, W - 72, 20, False)
    d.text((38, 76), t, font=f, fill=ART_MUTED)
    y = 120
    for x in data:
        d.rounded_rectangle((20, y, W - 20, y + (ROW if xray_hits(x) else SHORT) - 14), 22, fill=(12, 12, 18, 190), outline=(255, 255, 255, 22))
        t, f = fit_text(d, x["text"], 330 if xray_hits(x) else 520, 22, True)
        d.text((44, y + 22), t, font=f, fill=ART_TEXT)
        h = xray_hits(x)
        if h is None:
            wt, wf = fit_text(d, x["why"] or "no data", 500, 17, False)
            d.text((W - 44 - _tw(d, wt, wf), y + 26), wt, font=wf, fill=ART_MUTED)
            y += SHORT
            continue
        good, n = h
        rate = good / n
        colour = ART_GREEN if rate >= 0.6 else ART_AMBER if rate >= 0.4 else ART_RED
        d.text((44, y + 58), f"{good}/{n}", font=art_font(52, True), fill=colour)
        vals = [v for _, _, v in x["values"]]
        d.text((44, y + 122), f"{x['side']} {x['line']:g}  ·  avg {sum(vals) / len(vals):.1f}", font=art_font(18, True),
               fill=ART_MUTED)
        # bars
        cx0, cx1, cy0, cy1 = 440, W - 44, y + 22, y + ROW - 52
        top = max(vals + [x["line"]]) * 1.15 or 1
        bw = (cx1 - cx0) / max(len(vals), 1)
        ly = cy1 - (x["line"] / top) * (cy1 - cy0)
        for dx in range(int(cx0), int(cx1), 14):
            d.line((dx, ly, dx + 7, ly), fill=(150, 150, 168), width=2)
        for k, (opp, at, v) in enumerate(x["values"]):
            good_game = v > x["line"] if x["side"] == "over" else v < x["line"]
            bx = cx0 + k * bw + bw * 0.18
            by = cy1 - (v / top) * (cy1 - cy0)
            d.rounded_rectangle((bx, min(by, cy1 - 3), bx + bw * 0.64, cy1), 6, fill=ART_GREEN if good_game else ART_RED)
            vf = art_font(15, True)
            vt = f"{v:g}"
            d.text((bx + bw * 0.32 - _tw(d, vt, vf) / 2, min(by, cy1 - 3) - 20), vt, font=vf, fill=ART_TEXT)
            of = art_font(13)
            ot = ("@" if at == "@" else "") + opp
            d.text((bx + bw * 0.32 - _tw(d, ot, of) / 2, cy1 + 6), ot, font=of, fill=ART_MUTED)
        lt = f"{x['line']:g}"
        lf = art_font(15, True)
        d.text((cx0 - 10 - _tw(d, lt, lf), ly - 9), lt, font=lf, fill=ART_TEXT)
        y += ROW
    d.text((36, H - 40), "Last 10 games, oldest → newest · green = beat the number", font=art_font(15), fill=ART_FAINT)
    brand_sign(img, W - 36, H - 40, "PIMP-BOT", 15, variant="cool")
    return _design_png(img)


async def slip_xray_file(slip: dict, data: Optional[list] = None) -> Optional[discord.File]:
    data = data if data is not None else await slip_xray_data(slip)
    if not any(xray_hits(x) for x in data):
        return None
    title = " · ".join(x for x in (slip.get("platform"), slip.get("description")) if x)
    png = await asyncio.to_thread(locked_render, render_xray, title, data, "SLIP X-RAY", slip.get("sport"))
    return discord.File(png, filename="xray.png")


# ---- ghost slips -------------------------------------------------------------------------------

def _ensure_r15_tables():
    db().executescript("""
        CREATE TABLE IF NOT EXISTS ghosts (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            guild_id    INTEGER NOT NULL,
            user_id     INTEGER NOT NULL,
            user_name   TEXT,
            draft_mid   INTEGER NOT NULL,
            channel_id  INTEGER,
            reply_mid   INTEGER,
            sport       TEXT,
            description TEXT,
            legs        TEXT NOT NULL,
            cost        REAL,
            payout      REAL,
            created_at  TEXT NOT NULL,
            checked_at  TEXT,
            result      TEXT NOT NULL DEFAULT 'open',
            settled_at  TEXT,
            UNIQUE (guild_id, draft_mid)
        );
        CREATE TABLE IF NOT EXISTS leg_pings (
            pick_id INTEGER NOT NULL,
            idx     INTEGER NOT NULL,
            state   TEXT NOT NULL,
            PRIMARY KEY (pick_id, idx, state)
        );
    """)
    db().commit()


_r15_ready = False


def r15_db():
    global _r15_ready
    if not _r15_ready:
        _ensure_r15_tables()
        _r15_ready = True
    return db()


def add_ghost(guild_id: int, poster_id: int, poster_name: str, draft_mid: int, channel_id: int,
              reply_mid: Optional[int], slip: dict) -> None:
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()]
    if not legs:
        return
    r15_db().execute("""INSERT OR IGNORE INTO ghosts (guild_id, user_id, user_name, draft_mid, channel_id, reply_mid, sport,
                        description, legs, cost, payout, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
                     (guild_id, poster_id, poster_name, draft_mid, channel_id, reply_mid, slip.get("sport"),
                      str(slip.get("description") or "Slip")[:200],
                      json.dumps([{"idx": k, "text": t, "status": "open"} for k, t in enumerate(legs, 1)]),
                      slip.get("cost"), slip.get("payout"), now_iso()))
    db().commit()


def clear_matching_ghosts(guild_id: int, user_id: int, legs_text: Optional[str]) -> None:
    """They played it after all (logged by any route): drop open ghosts sharing at least half their legs."""
    mine = {norm_name(x) for x in (legs_text or "").splitlines() if x.strip()}
    if not mine:
        return
    for g in r15_db().execute("SELECT id, legs FROM ghosts WHERE guild_id = ? AND user_id = ? AND result = 'open'",
                              (guild_id, user_id)).fetchall():
        theirs = {norm_name(x["text"]) for x in json.loads(g["legs"])}
        if theirs and len(mine & theirs) * 2 >= len(theirs):
            db().execute("DELETE FROM ghosts WHERE id = ?", (g["id"],))
    db().commit()


def drop_ghost(guild_id: int, draft_mid: int) -> None:
    r15_db().execute("DELETE FROM ghosts WHERE guild_id = ? AND draft_mid = ? AND result = 'open'", (guild_id, draft_mid))
    db().commit()


def leg_outcome(e: dict) -> Optional[str]:
    """hit / miss / push once a leg is decided (an over that's cleared counts), else None."""
    if e.get("status") in ("hit", "miss", "push"):
        return e["status"]
    if e.get("live") in ("hit", "miss", "push"):
        return e["live"]
    if e.get("final") in ("hit", "miss", "push"):
        return e["final"]
    ev = e.get("event") or {}
    if (ev.get("final") or ev.get("state") == "post") and e.get("live") in ("ahead", "behind"):
        return "hit" if e["live"] == "ahead" else "miss"
    return None


GHOST_DAYS = 4


async def grade_ghosts(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    rows = r15_db().execute("SELECT * FROM ghosts WHERE result = 'open' AND (checked_at IS NULL OR checked_at < ?) "
                            "ORDER BY checked_at LIMIT 10", (iso(now - timedelta(minutes=8)),)).fetchall()
    for g in rows:
        db().execute("UPDATE ghosts SET checked_at = ? WHERE id = ?", (now_iso(), g["id"]))
        db().commit()
        if datetime.fromisoformat(g["created_at"]) < now - timedelta(days=GHOST_DAYS):
            db().execute("UPDATE ghosts SET result = 'expired', settled_at = ? WHERE id = ?", (now_iso(), g["id"]))
            db().commit()
            continue
        legs = json.loads(g["legs"])
        pseudo = {"id": -g["id"], "sport": g["sport"], "description": g["description"], "status": "open",
                  "created_at": g["created_at"]}
        try:
            entries = await leg_progress(pseudo, legs=legs)
        except Exception:
            log.warning("Ghost %s check failed", g["id"], exc_info=True)
            continue
        for leg, e in zip(legs, entries):
            got = leg_outcome(e)
            if got:
                leg["status"] = got
                if e.get("num") and e["num"].get("value") is not None:
                    leg["value"] = e["num"]["value"]
        db().execute("UPDATE ghosts SET legs = ? WHERE id = ?", (json.dumps(legs), g["id"]))
        db().commit()
        states = [x["status"] for x in legs]
        if "miss" in states:
            result = "miss"
        elif all(s in ("hit", "push") for s in states) and "hit" in states:
            result = "hit"
        else:
            continue
        db().execute("UPDATE ghosts SET result = ?, settled_at = ? WHERE id = ?", (result, now_iso(), g["id"]))
        db().commit()
        await announce_ghost(client, g, legs, result)


def ghost_line(g, legs: list, result: str) -> str:
    who = g["user_name"] or "you"
    if result == "hit":
        amt = f" ({signed(g['payout'] - g['cost'])})" if g["cost"] and g["payout"] else ""
        return (f"👻 **Ghost slip:** {who} passed on {clip(g['description'], 60)}, and it would've **hit**{amt}. 🫠 "
                f"Every leg came in.")
    miss = next((x for x in legs if x["status"] == "miss"), None)
    tail = f" {clip(miss['text'], 70)}" + (f" ({miss['value']:g})" if miss and miss.get("value") is not None else "") + \
           " sank it." if miss else ""
    return f"👻 **Ghost slip:** good pass, {who}. {clip(g['description'], 60)} would've **missed**.{tail}"


async def announce_ghost(client, g, legs: list, result: str) -> None:
    line = ghost_line(g, legs, result)
    channel = client.get_channel(g["channel_id"]) if g["channel_id"] else None
    if channel is None:
        return
    try:
        if g["reply_mid"]:
            ref = channel.get_partial_message(g["reply_mid"])
            ref = ref.to_reference(fail_if_not_exists=False) if hasattr(ref, "to_reference") else ref
            await channel.send(line, reference=ref, mention_author=False, allowed_mentions=discord.AllowedMentions.none())
        else:
            await channel.send(line, allowed_mentions=discord.AllowedMentions.none())
    except Exception:
        log.warning("Couldn't post ghost result %s", g["id"], exc_info=True)


def pass_record(guild_id: int, user_id: int) -> dict:
    rows = r15_db().execute("SELECT * FROM ghosts WHERE guild_id = ? AND user_id = ? AND result IN ('hit', 'miss') "
                            "ORDER BY settled_at DESC", (guild_id, user_id)).fetchall()
    good = [r for r in rows if r["result"] == "miss"]
    bad = [r for r in rows if r["result"] == "hit"]
    saved = sum(r["cost"] or 0 for r in good)
    missed = sum((r["payout"] or 0) - (r["cost"] or 0) for r in bad)
    open_n = r15_db().execute("SELECT COUNT(*) AS n FROM ghosts WHERE guild_id = ? AND user_id = ? AND result = 'open'",
                              (guild_id, user_id)).fetchone()["n"]
    return {"good": len(good), "bad": len(bad), "saved": saved, "missed": missed, "open": open_n, "rows": rows[:6]}


# ---- leg-by-leg DMs + sweat radio ------------------------------------------------------------------

_LEG_SEEN: dict[int, float] = {}


def leg_label(text: str) -> str:
    pr = cached_prop(text)
    if pr:
        return pr["display"].split()[-1] if len(pr["display"].split()) > 1 else pr["display"]
    return clip(text, 30)


async def leg_watch(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    r15_db()
    init = get_setting(0, "legwatch_init")
    if init is None:
        init = now_iso()
        set_setting(0, "legwatch_init", init)
    cutoff = iso(now - timedelta(days=3))
    recent = iso(now - timedelta(minutes=20))
    picks = db().execute("""SELECT * FROM picks WHERE (status = 'open' OR (settled_at >= ? AND id IN
                            (SELECT pick_id FROM leg_pings WHERE idx = 0))) AND created_at >= ?
                            AND bettor_id IS NOT NULL AND id IN (SELECT pick_id FROM legs)
                            ORDER BY id DESC LIMIT 60""", (recent, cutoff)).fetchall()
    spoken: dict[int, int] = {}
    said: set = set()
    checked = 0
    for p in picks:
        if checked >= 25:
            break
        if _LEG_SEEN.get(p["id"], 0) > time.monotonic() - 200:
            continue
        _LEG_SEEN[p["id"]] = time.monotonic()
        checked += 1
        entries = await cached_progress(p)
        sent = {(r["idx"], r["state"]) for r in db().execute("SELECT idx, state FROM leg_pings WHERE pick_id = ?", (p["id"],))}
        # picks that were already open when this feature arrived: record where they stand, don't DM about the past
        baseline = (0, "seen") not in sent and p["created_at"] <= init
        db().execute("INSERT OR IGNORE INTO leg_pings (pick_id, idx, state) VALUES (?, 0, 'seen')", (p["id"],))
        news, voice_lines = [], []
        for e in entries:
            out = leg_outcome(e)
            n = e.get("n")
            if out in ("hit", "miss") and (n, out) not in sent:
                db().execute("INSERT OR IGNORE INTO leg_pings (pick_id, idx, state) VALUES (?,?,?)", (p["id"], n, out))
                val = (e.get("num") or {}).get("value")
                news.append(("✅" if out == "hit" else "💀") + f" {clip(e['text'], 80)}: "
                            + ("cleared" if out == "hit" else "dead") + (f" ({val:g})" if val is not None else ""))
                voice_lines.append(f"{leg_label(e['text'])} clears for {p['bettor_name']}!" if out == "hit" else
                                   f"Ouch. {leg_label(e['text'])} is dead for {p['bettor_name']}.")
            num = e.get("num")
            if (out is None and num and num.get("side") == "over" and e.get("in_play") and num["line"] >= 1.5
                    and 0 < num["value"] < num["line"] and num["line"] - num["value"] <= max(1.0, num["line"] * 0.15)
                    and (n, "close") not in sent):
                db().execute("INSERT OR IGNORE INTO leg_pings (pick_id, idx, state) VALUES (?,?,?)", (p["id"], n, "close"))
                need = num["line"] - num["value"]
                voice_lines.append(f"{leg_label(e['text'])} is at {num['value']:g}. {p['bettor_name']} needs "
                                   f"{math.ceil(need) if need > 0.5 else 1} more.")
        db().commit()
        if baseline or (not news and not voice_lines):
            continue
        if news and get_setting(p["guild_id"], f"legalerts:{p['bettor_id']}") != "off" \
                and not is_quiet(p["guild_id"], p["bettor_id"], now):
            alive = sum(1 for e in entries if leg_outcome(e) != "miss")
            hits = sum(1 for e in entries if leg_outcome(e) == "hit")
            tail = (f"\n-# {hits}/{len(entries)} in" + ("" if alive == len(entries) else " · slip's dead") +
                    " · `/me legalerts` turns these off")
            try:
                user = await known_user(client, p["bettor_id"])
                user = user or await client.fetch_user(p["bettor_id"])
                for chunk in split_message(f"🎯 **{clip(p['description'], 60)}** (`#{p['id']}`)\n" + "\n".join(news) + tail):
                    await user.send(chunk)
            except Exception:
                log.info("Couldn't DM leg alert for pick %s", p["id"])
        if voice_lines and not p["hidden"] and p["guild_id"] in VOICE:
            for line in voice_lines:
                if spoken.get(p["guild_id"], 0) >= 4:
                    break
                if (p["guild_id"], line) in said:
                    continue
                said.add((p["guild_id"], line))
                spoken[p["guild_id"]] = spoken.get(p["guild_id"], 0) + 1
                await voice_say(client, p["guild_id"], line)
    if len(_LEG_SEEN) > 2000:
        _LEG_SEEN.clear()


# ==========================================================================
# r17: typed slips, "how's my slip?", /scout, posters, job health
# ==========================================================================

# ---- typed slips --------------------------------------------------------------------------------

LEGLIKE = re.compile(r"\b(?:over|under|more|less)\s?\d|\b[ou]\s?\d+\.5\b|\b\d+(?:\.\d+)?\s*\+(?!\d)"
                     r"|\b(?:ml|moneyline)\b|(?<![\w.$])[+-]\d{1,2}(?:\.5)?\b(?!\d)|\banytime\b", re.I)   # spreads, not -110 odds
TEXT_LOG = re.compile(r"^\s*(?:log|add|track(?! record)|record(?! of| with| on)|save|placed|played|locked in|i'?m on|im on|"
                      r"in on|tailing)\b", re.I)
TEXT_AMOUNT = re.compile(r"\$\s?\d|\bto (?:win|pay)\b", re.I)
QUESTION_START = re.compile(r"^\s*(?:who|what|whats|what's|when|where|why|which|is|are|does|do|did|can|could|odds|"
                            r"how many|how much|anyone|any)\b", re.I)
REVIEW_ASK = re.compile(r"\b(?:thoughts|rate (?:it|this|my)|review|break (?:it |this )?down|breakdown|what do (?:you|u|y'?all) think|"
                        r"should i (?:play|take|ride|tail|run)|would you (?:play|take|ride)|any good)\b", re.I)
STATUS_ASK = re.compile(r"\b(?:how(?:'s| is| are)|hows|where(?:'s| is| are)|update on|check(?: on)?)\b[^?]{0,25}\bmy\b"
                        r"[^?]{0,12}\b(?:slips?|parlays?|picks?|bets?|entries|entry|legs?)\b"
                        r"|\bmy\s+(?:slips?|parlays?|picks?|bets?)\s+(?:doing|looking|going|at)\b", re.I)
STATUS_NOT_NOW = re.compile(r"\b(?:season|year|month|week|record|rate|rank(?:ed)?|roi|profit|vs|versus|from|last|since|"
                            r"all[- ]time|leaderboard|history|overall|lifetime)\b", re.I)


def leg_hits(text: str) -> int:
    return len(LEGLIKE.findall(text))


def text_route(words: str) -> Optional[str]:
    """'status', 'log', 'review' or None (an ordinary question for the Q&A path)."""
    if STATUS_ASK.search(words) and not STATUS_NOT_NOW.search(words):
        return "status"
    hits = leg_hits(words)
    if not hits or len(words) < 6:
        return None
    if TEXT_LOG.search(words):
        return "log"
    question = bool(QUESTION_START.search(words)) or "?" in words
    if REVIEW_ASK.search(words) and (hits >= 2 or not QUESTION_START.search(words)):
        return "review"
    if TEXT_AMOUNT.search(words) and not question:
        return "log"
    if hits >= 2 and question and not QUESTION_START.search(words):
        return "review"
    return None
PLATFORM_WORDS = [(r"\bprize ?picks\b", "PrizePicks"), (r"\bkalshi\b", "Kalshi"), (r"\bunderdog\b", "Underdog"),
                  (r"\bdraft ?kings\b", "DraftKings"), (r"\bfan ?duel\b", "FanDuel")]
PLATFORM_ABBR = {"pp": "PrizePicks", "ud": "Underdog", "dk": "DraftKings", "fd": "FanDuel"}
PLATFORM_ABBR_RE = re.compile(r"(?:\b(?:on|via)\s+|@\s*)(pp|ud|dk|fd)\b|(?:,|^)\s*(pp|ud|dk|fd)\s*[,:]|\b(pp|ud|dk|fd)\s*$",
                              re.I)

TEXT_SLIP_PROMPT = """A member of a sports betting group typed a bet into Discord. Turn it into a slip.

Their message: <<<{text}>>>

Reply with ONLY a JSON object, no other text:
{{"is_slip": true or false, "platform": "PrizePicks" | "Kalshi" | a sportsbook name | "Other",
  "sport": short sport/league name or null, "description": one short line like "3-pick Power Play" or "2-leg parlay",
  "legs": ["one string per leg, written out in full: 'Player Name over|under LINE stat' (o/More = over, u/Less = \
under; '22.5+' = over 22.5), or 'Team ML', 'Team -3.5', 'Over 44.5'. Expand common nicknames to full names."],
  "cost": amount risked or null if not given, "payout": total paid back if it wins or null if not given}}
"$10 to win $30" means cost 10, payout 30. Numbers must be plain numbers. Never invent an amount."""


def text_slip_words(message) -> str:
    return re.sub(r"<@[!&]?\d+>", " ", getattr(message, "content", "") or "").strip()


def looks_like_legs(text: str) -> bool:
    return len(text) >= 6 and bool(LEGLIKE.search(text))


def parse_text_slip(text: str) -> Optional[dict]:
    """No-Claude fallback: legs split on new lines, commas, semicolons or ' + '; '$10 to win $30' amounts."""
    t = text
    cost = payout = None
    amt = r"(?<![\d,.])(\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?)"
    m = (re.search(r"(?:\$\s*)?" + amt + r"\s*(?:to win|to pay|pays|->|→)\s*\$?\s*" + amt, t, re.I)
         or re.search(r"\$\s*" + amt + r"\s*/\s*\$?\s*" + amt, t))
    if m:
        cost, payout = as_amount(m.group(1)), as_amount(m.group(2))
        t = t.replace(m.group(0), " ")
    else:
        m = re.search(r"(?:\bfor\s+|\brisk(?:ing)?\s+)?\$\s*" + amt, t, re.I)
        if m:
            cost = as_amount(m.group(1))
            t = t.replace(m.group(0), " ")
    platform = "Other"
    for pat, name in PLATFORM_WORDS:
        hit = re.search(pat, t, re.I)
        if hit:
            platform = name
            t = t[:hit.start()] + " " + t[hit.end():]
            break
    else:
        hit = PLATFORM_ABBR_RE.search(t)
        if hit:
            platform = PLATFORM_ABBR[(hit.group(1) or hit.group(2) or hit.group(3)).lower()]
            t = t[:hit.start()] + " , " + t[hit.end():]
    t = TEXT_LOG.sub(" ", t)
    t = re.sub(r"\b(this|these|for me|please|pls|slip|parlay|my|on)\b", " ", t, flags=re.I)
    parts, glue = [], False
    for k, bit in enumerate(re.split(r"(\n|;|,|\s\+\s|\s&\s|\s+and\s+)", t)):
        if k % 2:      # a separator: " + " right after a bare name is a two-player combo, not a new leg
            glue = bit.strip() == "+" and bool(parts) and not LEGLIKE.search(parts[-1])
            continue
        bit = bit.strip(" -–•*:")
        if bit and glue:
            parts[-1] += " + " + bit
        elif bit:
            parts.append(bit)
        glue = False
    legs = []
    for p in parts:
        if not LEGLIKE.search(p):
            continue
        p = re.sub(r"(?i)\bo\s?(\d+(?:\.\d+)?)\b", r"over \1", p)
        p = re.sub(r"(?i)\bu\s?(\d+(?:\.\d+)?)\b", r"under \1", p)
        legs.append(" ".join(p.split()))
    if not legs:
        return None
    legs = legs[:20]
    return {"is_slip": True, "platform": platform, "sport": None,
            "description": f"{len(legs)}-leg slip" if len(legs) > 1 else "Single", "legs": legs, "cost": cost,
            "payout": payout, "returned": None, "status": "open", "placed": True}


async def read_text_slip(text: str) -> tuple[Optional[dict], Optional[str]]:
    if not ai_enabled():
        slip = parse_text_slip(text)
        return slip, None if slip else "I couldn't find any legs in that"
    try:
        reply = await asyncio.wait_for(anthropic_client().messages.create(
            model=CLAUDE_MODEL, max_tokens=800,
            messages=[{"role": "user", "content": TEXT_SLIP_PROMPT.format(text=text[:1500])}]), timeout=25)
        slip = extract_json("".join(b.text for b in reply.content if getattr(b, "type", "") == "text"))
    except Exception as exc:
        log.warning("Typed slip read failed; using the simple parser", exc_info=True)
        slip = parse_text_slip(text)
        return slip, None if slip else explain_ai_error(exc)[0]
    if not slip.get("is_slip") or not slip.get("legs"):
        return None, "not_slip"
    legs = slip["legs"]
    if isinstance(legs, str):
        legs = [x for x in re.split(r"\n|;", legs)]
    slip["legs"] = [str(x).strip() for x in legs if str(x).strip()][:20]
    if not slip["legs"]:
        return None, "not_slip"
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip.update(returned=None, status="open", placed=True)
    return slip, None


def slip_draft_embed(slip: dict, title: str = "🧾 Log this slip?") -> discord.Embed:
    legs = [str(x) for x in slip.get("legs") or []]
    e = discord.Embed(title=title, color=BRAND,
                      description=clip("\n".join(f"`{k}` {leg}" for k, leg in enumerate(legs, 1)), 3500) or "No legs")
    e.add_field(name="Platform", value=str(slip.get("platform") or "Other")[:40])
    e.add_field(name="Play", value=clip(str(slip.get("description") or "Slip"), 100))
    if slip.get("cost"):
        e.add_field(name="Riding", value=f"{money(slip['cost'])} → {money(slip['payout'] or 0)}" +
                    ("" if slip.get("payout") else " (payout missing: tap ✏️ Edit)"))
    else:
        e.add_field(name="Riding", value="Amounts missing: tap ✏️ Edit")
    e.set_footer(text="Nothing's logged until you tap ✅ Log it.")
    return e


class DraftEditModal(discord.ui.Modal, title="Edit before logging"):
    platform = discord.ui.TextInput(label="Platform", max_length=40)
    description = discord.ui.TextInput(label="The play", max_length=200)
    legs = discord.ui.TextInput(label="Legs (one per line)", style=discord.TextStyle.paragraph, max_length=900)
    cost = discord.ui.TextInput(label="Cost / entry", max_length=12)
    payout = discord.ui.TextInput(label="Pays if it wins", max_length=12)

    def __init__(self, message_id: int, d: dict):
        super().__init__()
        self.message_id = message_id
        slip = d["slip"]
        self.platform.default = str(slip.get("platform") or "Other")[:40]
        self.description.default = str(slip.get("description") or "Slip")[:200]
        self.legs.default = "\n".join(str(x) for x in slip.get("legs") or [])[:900]
        self.cost.default = f"{slip['cost']:.2f}" if slip.get("cost") is not None else None
        self.payout.default = f"{slip['payout']:.2f}" if slip.get("payout") is not None else None

    async def on_submit(self, interaction: discord.Interaction):
        d = get_slip_draft(interaction.guild_id, self.message_id)
        if d is None or interaction.user.id != d["poster"] or d.get("used"):
            await interaction.response.send_message("That slip isn't yours to log, or it's already logged.", ephemeral=True)
            return
        try:
            cost, payout = parse_money(self.cost.value), parse_money(self.payout.value)
        except ValueError:
            await interaction.response.send_message("Cost and payout need to be amounts, like 10 or $10.", ephemeral=True)
            return
        if cost <= 0:
            await interaction.response.send_message("Cost has to be more than 0.", ephemeral=True)
            return
        until = cooling_until(interaction.guild_id, interaction.user.id)
        if until:
            await interaction.response.send_message(cooloff_message(until), ephemeral=True)
            return
        legs = [x.strip() for x in self.legs.value.splitlines() if x.strip()]
        old_legs = list(d["slip"].get("legs") or [])
        remember_scan_edits(old_legs, legs)
        for old, new in zip(old_legs, legs):
            if old.strip() and old.strip() != new.strip():
                staff_log_add(interaction.guild_id, "edit", f"Edit kept the old line: {clip(old, 140)}",
                              getattr(interaction.user, "display_name", "") or "")
                break
        d["slip"].update(platform=self.platform.value.strip() or "Other", description=self.description.value.strip() or "Slip",
                         legs=legs, cost=cost, payout=payout, placed=True)
        d["used"] = -1
        set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
        await interaction.response.defer()

        async def reply(**kw):
            return await interaction.followup.send(wait=True, **kw)
        bettor = None
        if can_file_for_others(interaction.user, interaction.guild_id) and d.get("for_id"):
            bettor = _FiledWho(int(d["for_id"]), d.get("for_name") or "them")
        try:
            pid = await interaction.client.log_parsed_slip(interaction.guild_id, interaction.user, interaction.channel,
                                                           d["slip"], d["url"], reply, bettor=bettor)
        except Exception:
            log.exception("Logging an edited draft failed")
            d["used"] = None
            set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
            await interaction.followup.send("⚠️ Something went wrong logging that. Try ✏️ Edit again.", ephemeral=True)
            return
        d["used"] = pid
        set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
        drop_ghost(interaction.guild_id, self.message_id)


# ---- "how's my slip doing?" -------------------------------------------------------------------------

async def slip_status_files(client, guild_id: int, user_id: int, limit: int = 3) -> tuple[list, int]:
    cutoff = iso(datetime.now(timezone.utc) - timedelta(days=4))
    picks = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_id = ? AND status = 'open' AND created_at >= ? "
                         "AND (hidden IS NULL OR hidden = 0) ORDER BY id DESC", (guild_id, user_id, cutoff)).fetchall()
    files = []
    for p in picks[:limit]:
        try:
            files.append(await receipt_file(client, p))
        except Exception:
            log.warning("Status receipt failed for pick %s", p["id"], exc_info=True)
    return files, len(picks)


# ---- /scout ----------------------------------------------------------------------------------------

async def scout_data(cand: dict, stat: Optional[str] = None, line: Optional[float] = None) -> tuple[list, list]:
    """(X-ray rows for the player's main stats, the raw games)."""
    fam = FAMILY_OF_PATH[cand["path"]]
    games = await trend_games(cand["path"], cand["id"], need=10)
    keys = [stat] if stat else [k for k in MAIN_STATS.get(fam, []) if k in STATS and k != "minutes"]
    rows = []
    for k in keys:
        vals = trend_values(games, k)[:10]
        if not vals or (not stat and sum(v for _, v in vals) == 0):
            continue
        ln = float(line) if (stat and line is not None) else default_line([v for _, v in vals])
        rows.append({"text": f"{STATS[k][0]} · line {ln:g}", "values": [(g["opp"], g["at"], v) for g, v in vals][::-1],
                     "line": ln, "side": "over", "name": cand["name"], "stat": STATS[k][0], "why": "", "key": k})
    return rows[:4], games


# ---- posters ----------------------------------------------------------------------------------------

POSTER_TITLE = 46
POSTER_SUB = 22


def render_cashed_poster(title: str, sub: str, receipts: list[io.BytesIO]) -> io.BytesIO:
    from PIL import Image, ImageDraw
    thumbs = []
    for r in receipts[:6]:
        r.seek(0)
        im = Image.open(r).convert("RGB")
        w = 470
        thumbs.append(im.resize((w, int(im.height * w / im.width)), Image.LANCZOS))
    cols = 2 if len(thumbs) > 1 else 1
    W = 40 + cols * 470 + (cols - 1) * 20 + 40
    col_h = [0] * cols
    places = []
    for t in thumbs:
        c = col_h.index(min(col_h))
        places.append((c, col_h[c]))
        col_h[c] += t.height + 20
    H = 190 + max(col_h or [0]) + 40
    img, d = _design_card(W, H, "stadium", (20, 120, 80), (90, 230, 160), head=200, margin=0, radius=0)
    t, f = fit_text(d, title, W - 80, POSTER_TITLE, True)
    d.text((40, 36), t, font=f, fill=ART_TEXT)
    d.text((42, 104), sub, font=art_font(POSTER_SUB, True), fill=ART_GREEN)
    for th, (c, y) in zip(thumbs, places):
        d.rounded_rectangle((34 + c * 490, 174 + y, 46 + c * 490 + th.width, 186 + y + th.height), 34,
                            fill=(0, 0, 0, 110))
        img.paste(th, (40 + c * 490, 180 + y))
    brand_sign(img, W - 40, H - 34, "PIMP-BOT", 15, variant="hype")
    return _design_png(img)


def render_standings_poster(title: str, sub: str, rows: list[dict]) -> io.BytesIO:
    """rows: rank, name, avatar, record, net, roi, move"""
    from PIL import Image, ImageDraw
    W, RH = 900, 92
    rows = rows[:12]
    H = 210 + RH * len(rows) + 50
    img, d = _design_card(W, H, "stadium", (150, 110, 20), (255, 214, 102), head=210, margin=0, radius=0)
    t, f = fit_text(d, title, W - 80, POSTER_TITLE, True)
    d.text((40, 36), t, font=f, fill=ART_TEXT)
    d.text((42, 104), sub, font=art_font(POSTER_SUB, True), fill=ART_MUTED)
    medal = {1: (255, 214, 102), 2: (210, 216, 226), 3: (214, 150, 90)}
    y = 205
    for r in rows:
        d.rounded_rectangle((24, y, W - 24, y + RH - 12), 20, fill=(12, 12, 18, 190) if r["rank"] > 3 else (40, 34, 20, 206),
                            outline=(255, 255, 255, 22) if r["rank"] > 3 else medal[r["rank"]] + (120,))
        rc = medal.get(r["rank"], ART_MUTED)
        rt = str(r["rank"])
        d.text((70 - _tw(d, rt, art_font(32, True)) / 2, y + 18), rt, font=art_font(32, True), fill=rc)
        av = _avatar(r.get("avatar"), 58, r["name"], -1)
        img.paste(av, (110, y + 11), av)
        t, f = fit_text(d, r["name"], 300, 28, True)
        d.text((186, y + 12), t, font=f, fill=ART_TEXT)
        d.text((188, y + 48), r["record"], font=art_font(18, True), fill=ART_MUTED)
        mv = r.get("move") or 0
        if mv:
            arrow = ("▲" if mv > 0 else "▼") + str(abs(mv))
            d.text((W - 330, y + 26), arrow, font=art_font(22, True), fill=ART_GREEN if mv > 0 else ART_RED)
        net = signed_short(r["net"])
        t, f = fit_text(d, net, 200, 30, True)
        d.text((W - 56 - _tw(d, t, f), y + 12), t, font=f, fill=ART_GREEN if r["net"] >= 0 else ART_RED)
        roi = f"{r['roi']:+.0f}% ROI"
        d.text((W - 56 - _tw(d, roi, art_font(17, True)), y + 50), roi, font=art_font(17, True), fill=ART_MUTED)
        y += RH
    brand_sign(img, W - 40, H - 36, "PIMP-BOT", 15, variant="crown")
    return _design_png(img)


async def cashed_poster_file(client, guild_id: int, days: int = 7) -> Optional[discord.File]:
    since = iso(datetime.now(timezone.utc) - timedelta(days=days))
    wins = db().execute("SELECT * FROM picks WHERE guild_id = ? AND status = 'win' AND settled_at >= ? AND "
                        "(hidden IS NULL OR hidden = 0 OR revealed_at IS NOT NULL)", (guild_id, since)).fetchall()
    wins = sorted(wins, key=pick_net, reverse=True)[:6]
    if not wins:
        return None
    receipts = []
    for p in wins:
        user = (await known_user(client, p["bettor_id"]) if p["bettor_id"] else None)
        av = await avatar_bytes(user) if user else None
        receipts.append(await asyncio.to_thread(locked_render, render_receipt, receipt_data(p, db_entries(p), av)))
    total = sum(pick_net(p) for p in wins)
    png = await asyncio.to_thread(locked_render, render_cashed_poster, "CASHED THIS WEEK" if days == 7 else
                                  f"CASHED · LAST {days} DAYS", f"{signed_short(total)} across {len(wins)} slip"
                                  f"{'s' if len(wins) != 1 else ''}", receipts)
    return discord.File(png, filename="cashed.png")


async def standings_poster_file(client, guild_id: int, period: str = "season", back: bool = False) -> Optional[discord.File]:
    now = datetime.now(timezone.utc)
    until = None
    since = None if period == "season" else iso(now - timedelta(days=7 if period == "week" else 30))
    season = current_season(guild_id) if period == "season" else None
    if season is not None:
        since = season["started_at"]
    if period == "month" and back:
        since = iso(now - timedelta(days=60))
        until = iso(now - timedelta(days=30))
        season = None
    stats = [s for s in compute_stats(guild_id, since=since, until=until) if s["wins"] + s["losses"] + s["pushes"] > 0]
    if not stats:
        return None
    moves = rank_movement(guild_id, [s["key"] for s in stats], since, None) if period == "season" else {}
    top = stats[:12]
    users = [(await known_user(client, int(s["key"])) if s["key"].isdigit() else None) for s in top]

    async def av(u):
        return await avatar_bytes(u) if u else None
    avatars = await asyncio.gather(*(av(u) for u in users))
    rows = [{"rank": k, "name": s["name"], "avatar": a, "record": record_line(s), "net": s["net"], "roi": s["roi"],
             "move": moves.get(s["key"], 0)} for k, (s, a) in enumerate(zip(top, avatars), 1)]
    label = {"season": f"{season['name'].upper()} STANDINGS" if season is not None else "ALL-TIME STANDINGS",
             "week": "THIS WEEK", "month": "PREVIOUS MONTH" if back else "LAST 30 DAYS"}[period]
    png = await asyncio.to_thread(locked_render, render_standings_poster, label,
                                  datetime.now(TZ).strftime("%b %-d, %Y"), rows)
    return discord.File(png, filename="standings.png")


# ---- background job health -----------------------------------------------------------------------------

JOB_HEALTH: dict[str, dict] = {}
JOB_ALERT_AFTER = 5


def job_name(job) -> str:
    name = getattr(job, "__name__", "job")
    if name == "<lambda>":
        names = [n for n in getattr(getattr(job, "__code__", None), "co_names", ()) if n not in ("astimezone",)]
        return names[0] if names else "job"
    return name


def job_recently_clean(name: str, within: float = 90) -> bool:
    """True when this job finished with no error a moment ago, so this cycle can leave it alone."""
    h = JOB_HEALTH.get(name)
    if not h or h.get("fails") or not h.get("ok_at"):
        return False
    try:
        age = (datetime.now(timezone.utc) - datetime.fromisoformat(h["ok_at"])).total_seconds()
    except (TypeError, ValueError):
        return False
    return 0 <= age < within


def record_job(name: str, error: Optional[BaseException]) -> Optional[str]:
    """Track a run; returns an alert line the first time a job has failed JOB_ALERT_AFTER times in a row."""
    h = JOB_HEALTH.setdefault(name, {"fails": 0, "last_error": None, "alerted": False, "ok_at": None})
    if error is None:
        recovered = h["alerted"]
        h.update(fails=0, ok_at=now_iso(), alerted=False)
        return f"✅ Background job `{name}` is working again." if recovered else None
    h["fails"] += 1
    h["last_error"] = sec_redact(f"{type(error).__name__}: {error}")[:200]
    if h["fails"] >= JOB_ALERT_AFTER and not h["alerted"]:
        h["alerted"] = True
        return (f"⚠️ Background job `{name}` has failed {h['fails']} times in a row: `{h['last_error']}`. "
                "Everything else keeps running; Railway's logs have the details.")
    return None


def job_health_line() -> str:
    bad = {k: v for k, v in JOB_HEALTH.items() if v["fails"]}
    if not JOB_HEALTH:
        return "not run yet"
    if not bad:
        return f"✅ all {len(JOB_HEALTH)} healthy"
    return "⚠️ " + " · ".join(f"`{k}` failing ×{v['fails']}" for k, v in list(bad.items())[:5])


