# ---- real Discord pictures on cards, and a pulsing LIVE dot ---------------------------------------------------

_USER_CACHE: dict = {}


async def known_user(client, uid):
    """The Discord user for an id: from the cache, else one API lookup (kept 6 hours). Without the members intent
    most people aren't cached, which is why cards used to show initials instead of profile pictures."""
    if client is None or not uid:
        return None
    try:
        uid = int(uid)
    except (TypeError, ValueError):
        return None
    u = client.get_user(uid) if hasattr(client, "get_user") else None
    if u is not None:
        return u
    hit = _USER_CACHE.get(uid)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    u = None
    if hasattr(client, "fetch_user"):
        try:
            u = await asyncio.wait_for(client.fetch_user(uid), 5)
        except Exception:
            u = None
    _USER_CACHE[uid] = (time.monotonic() + (6 * 3600 if u is not None else 900), u)
    if len(_USER_CACHE) > 2000:
        for k in list(_USER_CACHE)[:1000]:
            _USER_CACHE.pop(k, None)
    return u


LV2_PULSE_FRAMES = 10


def lv2_pulse_gif(png: io.BytesIO) -> Optional[io.BytesIO]:
    """The same picture as an animated GIF whose LIVE dot fades in and out. None when there's no dot to pulse."""
    from PIL import Image, ImageDraw
    boxes = getattr(png, "pulse", None)
    if not boxes:
        return None
    png.seek(0)
    base = Image.open(png).convert("RGB")
    png.seek(0)
    red = ART_RED
    samples = []
    for (x0, y0, x1, y1) in boxes:
        samples.append(base.getpixel((max(0, int(x0) - 6), int((y0 + y1) / 2))))
    levels = [0.25 + 0.75 * (0.5 - 0.5 * math.cos(2 * math.pi * k / LV2_PULSE_FRAMES)) for k in range(LV2_PULSE_FRAMES)]
    # one palette for every frame: the picture's own colours plus every shade of the fade, so the pulse is smooth
    fades = []
    for bg in samples:
        for t in levels:
            for c in (_brand_mix(red, bg, 1 - t), _brand_mix(red, bg, 1 - t * 0.35)):
                if c not in fades:
                    fades.append(c)
    fades = fades[:96]
    room = 256 - len(fades)
    own = base.quantize(colors=room, method=Image.Quantize.MEDIANCUT).getpalette()[:room * 3]
    own += [0] * (room * 3 - len(own))
    pal = Image.new("P", (1, 1))
    pal.putpalette(own + [v for c in fades for v in c])
    frames = []
    for t in levels:
        f = base.copy()
        fd = ImageDraw.Draw(f)
        for (x0, y0, x1, y1), bg in zip(boxes, samples):
            r = (x1 - x0) / 2
            cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
            glow = r * (1.0 + 0.6 * t)
            fd.ellipse((cx - glow, cy - glow, cx + glow, cy + glow), fill=_brand_mix(red, bg, 1 - t * 0.35))
            fd.ellipse((cx - r, cy - r, cx + r, cy + r), fill=_brand_mix(red, bg, 1 - t))
        frames.append(f.quantize(palette=pal, dither=Image.Dither.NONE))
    out = io.BytesIO()
    frames[0].save(out, "GIF", save_all=True, append_images=frames[1:], duration=110, loop=0, optimize=False,
                   disposal=1)
    out.seek(0)
    return out


async def lv2_animated(png: io.BytesIO, stem: str):
    """(file, filename): the pulsing GIF when the picture has a LIVE dot, else the PNG."""
    try:
        gif = await asyncio.to_thread(lv2_pulse_gif, png)
    except Exception:
        log.warning("Pulsing dot failed; sending the still picture", exc_info=True)
        gif = None
    if gif is not None and gif.getbuffer().nbytes < 7 * 1024 * 1024:
        return discord.File(gif, filename=f"{stem}.gif"), f"{stem}.gif"
    png.seek(0)
    return discord.File(png, filename=f"{stem}.png"), f"{stem}.png"


# ---- team crests: an original emblem per team, from its colours (never a real logo) ----------------------------

_CREST_CACHE: dict = {}
LV2_SPORT_OF_LEAGUE = {"NFL": "football", "College football": "football", "NBA": "basketball", "WNBA": "basketball",
                       "College basketball": "basketball", "NHL": "hockey", "MLB": "baseball"}


def lv2_sport(league: Optional[str]) -> str:
    return LV2_SPORT_OF_LEAGUE.get(league or "", "soccer" if league else "other")


def _crest_glyph(d, cx: float, cy: float, s: float, sport: str, ink: tuple) -> None:
    """A small sport mark: a football, basketball, puck, baseball or soccer ball, drawn with plain shapes."""
    w = max(2, int(s * 0.09))
    if sport == "football":
        d.ellipse((cx - s * 0.62, cy - s * 0.36, cx + s * 0.62, cy + s * 0.36), outline=ink, width=w)
        d.line((cx - s * 0.26, cy, cx + s * 0.26, cy), fill=ink, width=w)
        for k in (-0.14, 0, 0.14):
            d.line((cx + s * k, cy - s * 0.1, cx + s * k, cy + s * 0.1), fill=ink, width=max(1, w // 2))
    elif sport == "basketball":
        d.ellipse((cx - s * 0.45, cy - s * 0.45, cx + s * 0.45, cy + s * 0.45), outline=ink, width=w)
        d.line((cx - s * 0.45, cy, cx + s * 0.45, cy), fill=ink, width=w)
        d.line((cx, cy - s * 0.45, cx, cy + s * 0.45), fill=ink, width=w)
        d.arc((cx - s * 0.75, cy - s * 0.45, cx - s * 0.05, cy + s * 0.45), -60, 60, fill=ink, width=w)
        d.arc((cx + s * 0.05, cy - s * 0.45, cx + s * 0.75, cy + s * 0.45), 120, 240, fill=ink, width=w)
    elif sport == "hockey":
        d.ellipse((cx - s * 0.55, cy - s * 0.12, cx + s * 0.55, cy + s * 0.3), fill=ink)
        d.ellipse((cx - s * 0.55, cy - s * 0.3, cx + s * 0.55, cy + s * 0.12), outline=ink, width=w)
    elif sport == "baseball":
        d.ellipse((cx - s * 0.45, cy - s * 0.45, cx + s * 0.45, cy + s * 0.45), outline=ink, width=w)
        d.arc((cx - s * 0.85, cy - s * 0.5, cx - s * 0.12, cy + s * 0.5), -50, 50, fill=ink, width=max(1, w // 2 + 1))
        d.arc((cx + s * 0.12, cy - s * 0.5, cx + s * 0.85, cy + s * 0.5), 130, 230, fill=ink, width=max(1, w // 2 + 1))
    elif sport == "soccer":
        d.ellipse((cx - s * 0.45, cy - s * 0.45, cx + s * 0.45, cy + s * 0.45), outline=ink, width=w)
        pts = [(cx + s * 0.18 * math.cos(math.radians(a)), cy + s * 0.18 * math.sin(math.radians(a)))
               for a in range(-90, 270, 72)]
        d.polygon(pts, fill=ink)
    else:
        d.regular_polygon((cx, cy, s * 0.4), 5, fill=ink)


def team_crest_img(abbr: str, colour: tuple, alt: Optional[str], sport: str, size: int):
    """An RGBA emblem for one team: shape and stripe pattern picked from the abbreviation (so every team looks
    different, and the same every time), in the team's colours, with a sport mark and the abbreviation."""
    from PIL import Image, ImageDraw, ImageFilter
    key = (abbr, colour, alt, sport, size)
    hit = _CREST_CACHE.get(key)
    if hit is not None:
        return hit.copy()
    S = 4
    n = size * S
    seed = sum((i + 1) * ord(ch) for i, ch in enumerate(abbr or "?"))
    shape, pattern = seed % 3, (seed // 3) % 4
    second = _lv_hex(alt)
    if second is None or sum(abs(a - b) for a, b in zip(second, colour)) < 110 or _lv_lum(second) < 30:
        second = _brand_mix(colour, (255, 255, 255), 0.7)
    m = int(n * 0.06)
    if shape == 0:      # shield
        poly = [(m, m), (n - m, m), (n - m, n * 0.55), (n / 2, n - m), (m, n * 0.55)]
    elif shape == 1:    # hexagon
        poly = [(n / 2 + (n / 2 - m) * math.cos(math.radians(a)), n / 2 + (n / 2 - m) * math.sin(math.radians(a)))
                for a in range(-90, 270, 60)]
    else:               # diamond-cut badge
        c = n * 0.22
        poly = [(m + c, m), (n - m - c, m), (n - m, m + c), (n - m, n - m - c), (n - m - c, n - m), (m + c, n - m),
                (m, n - m - c), (m, m + c)]
    mask = Image.new("L", (n, n), 0)
    ImageDraw.Draw(mask).polygon(poly, fill=255)
    body = _vgrad((n, n), _brand_mix(colour, (255, 255, 255), 0.18), _brand_mix(colour, (0, 0, 0), 0.38)).convert("RGBA")
    stripe = Image.new("RGBA", (n, n), (0, 0, 0, 0))
    sd = ImageDraw.Draw(stripe)
    band = second + (235,)
    if pattern == 0:    # diagonal sash
        sd.polygon([(0, n * 0.62), (n * 0.62, 0), (n * 0.86, 0), (0, n * 0.86)], fill=band)
    elif pattern == 1:  # chevron
        sd.polygon([(0, n * 0.48), (n / 2, n * 0.72), (n, n * 0.48), (n, n * 0.62), (n / 2, n * 0.86), (0, n * 0.62)], fill=band)
    elif pattern == 2:  # split halves
        sd.rectangle((n / 2, 0, n, n), fill=second + (90,))
        sd.rectangle((n / 2 - n * 0.03, 0, n / 2 + n * 0.03, n), fill=band)
    else:               # two bands
        sd.rectangle((0, n * 0.66, n, n * 0.72), fill=band)
        sd.rectangle((0, n * 0.77, n, n * 0.8), fill=band)
    body.alpha_composite(stripe)
    out = Image.new("RGBA", (n, n), (0, 0, 0, 0))
    glow = Image.new("RGBA", (n, n), colour + (0,))
    gm = mask.filter(ImageFilter.GaussianBlur(n * 0.04)).point(lambda v: int(v * 0.45))
    glow.putalpha(gm)
    out.alpha_composite(glow)
    out.paste(body, (0, 0), mask)
    od = ImageDraw.Draw(out)
    od.polygon(poly, outline=(255, 255, 255, 210), width=int(n * 0.035))
    ink = (255, 255, 255, 235)
    _crest_glyph(od, n / 2, n * 0.27, n * 0.27, sport, ink)
    txt = (abbr or "?")[:4]
    f = art_font(int(n * (0.25 if len(txt) <= 2 else 0.22 if len(txt) == 3 else 0.18)), True)
    tw = od.textlength(txt, font=f)
    bb = f.getbbox(txt)
    ty = n * 0.62 - (bb[1] + bb[3]) / 2
    od.text((n / 2 - tw / 2 + n * 0.012, ty + n * 0.012), txt, font=f, fill=(0, 0, 0, 120))
    od.text((n / 2 - tw / 2, ty), txt, font=f, fill=(255, 255, 255, 255))
    small = out.resize((size, size), Image.LANCZOS)
    _CREST_CACHE[key] = small
    if len(_CREST_CACHE) > 300:
        for k in list(_CREST_CACHE)[:150]:
            _CREST_CACHE.pop(k, None)
    return small.copy()


def lv2_crest(img, cx: int, cy: int, r: int, team: dict, colour: tuple, sport: str) -> None:
    """Paste a team's crest centred at (cx, cy), about the size of a radius-r badge."""
    size = int(r * 2.3)
    if team.get("logo_bytes"):
        try:
            plate = _lv2_logo_plate(team["logo_bytes"], size, colour)
            img.paste(plate, (int(cx - size / 2), int(cy - size / 2)), plate)
            return
        except Exception:
            pass                               # a broken image: fall back to the crest
    crest = team_crest_img(lv_abbr(team), colour, team.get("alt_color"), sport, size)
    img.paste(crest, (int(cx - size / 2), int(cy - size / 2)), crest)


# ---- team logos from the scoreboard feed (the crest is only the fallback) --------------------------------------

_LOGO_CACHE: dict = {}
LV2_LOGO_HOSTS = ("a.espncdn.com", "a1.espncdn.com", "a2.espncdn.com", "a3.espncdn.com", "a4.espncdn.com")


async def team_logo_bytes(url: Optional[str]) -> Optional[bytes]:
    """The team's logo image from ESPN's own scoreboard feed (kept a day). Only ESPN's image host is fetched."""
    if not url:
        return None
    from urllib.parse import urlsplit
    parts = urlsplit(url)
    if parts.scheme != "https" or parts.hostname not in LV2_LOGO_HOSTS:
        return None
    hit = _LOGO_CACHE.get(url)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    raw = None
    try:
        import aiohttp
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=8)) as session:
            async with session.get(url) as resp:
                if resp.status == 200 and int(resp.headers.get("Content-Length") or 0) <= 1_500_000:
                    data = b""
                    while len(data) <= 1_500_000:
                        chunk = await resp.content.read(65536)
                        if not chunk:
                            break
                        data += chunk
                    raw = data if 0 < len(data) <= 1_500_000 else None
    except Exception:
        raw = None
    _LOGO_CACHE[url] = (time.monotonic() + (86400 if raw else 1800), raw)
    if len(_LOGO_CACHE) > 400:
        for k in list(_LOGO_CACHE)[:200]:
            _LOGO_CACHE.pop(k, None)
    return raw


async def lv2_attach_logos(*teams: dict) -> None:
    """Fetch each team's logo before the render thread (renderers never touch the network)."""
    for t in teams:
        if t is not None and not t.get("logo_bytes"):
            t["logo_bytes"] = await team_logo_bytes(t.get("logo"))


def _lv2_logo_plate(raw: bytes, size: int, colour: tuple):
    """The logo centred on a dark disc with a ring in the team's colour."""
    from PIL import Image, ImageDraw, ImageFilter
    logo = Image.open(io.BytesIO(raw))
    sec_check_image(logo)
    logo = logo.convert("RGBA")
    S = 3
    n = size * S
    out = Image.new("RGBA", (n, n), (0, 0, 0, 0))
    glow = Image.new("RGBA", (n, n), colour + (0,))
    gm = Image.new("L", (n, n), 0)
    ImageDraw.Draw(gm).ellipse((n * 0.04, n * 0.04, n * 0.96, n * 0.96), fill=150)
    glow.putalpha(gm.filter(ImageFilter.GaussianBlur(n * 0.04)))
    out.alpha_composite(glow)
    d = ImageDraw.Draw(out)
    d.ellipse((n * 0.06, n * 0.06, n * 0.94, n * 0.94), fill=(250, 250, 252, 255), outline=colour + (255,),
              width=max(2, int(n * 0.04)))
    box = int(n * 0.66)
    logo.thumbnail((box, box), Image.LANCZOS)
    out.alpha_composite(logo, (int((n - logo.width) / 2), int((n - logo.height) / 2)))
    return out.resize((size, size), Image.LANCZOS)


# ==========================================================================
# r26: the ask channel. Any message there is a question for the bot (no @mention needed), and the bot posts a
# news feed there: injury-report changes for players on the group's open slips, players coming off the report,
# and PrizePicks-style reboots when a player doesn't play.
# ==========================================================================

NEWS_EVERY_MIN = 10           # how often the injury reports are checked per server
NEWS_MAX_POSTS = 6            # updates posted one by one per check; more than this become one roundup
NEWS_STATUS_ICON = {"out": "⛔", "doubtful": "🟠", "questionable": "🟡", "day-to-day": "🟡", "suspension": "🚫",
                    "probable": "🟢", "active": "✅"}


def news_db():
    c = db()
    c.execute("""CREATE TABLE IF NOT EXISTS news_seen (
                     guild_id INTEGER NOT NULL, key TEXT NOT NULL, status TEXT, detail TEXT, posted_at TEXT,
                     PRIMARY KEY (guild_id, key))""")
    return c


def ask_channel_id(guild_id: int) -> Optional[int]:
    v = get_setting(guild_id, "ask_channel")
    return int(v) if v and v.isdigit() else None


def is_ask_channel(channel) -> bool:
    """The ask channel itself, or a thread inside it."""
    gid = getattr(getattr(channel, "guild", None), "id", None)
    if gid is None:
        return False
    cid = ask_channel_id(gid)
    return bool(cid) and (getattr(channel, "id", None) == cid or getattr(channel, "parent_id", None) == cid)


def news_icon(status: str) -> str:
    s = (status or "").lower()
    return next((v for k, v in NEWS_STATUS_ICON.items() if s.startswith(k)), "🩹")


async def news_watchlist(gid: int, now: datetime) -> dict[str, dict]:
    """{player key: {name, paths, slips: [(who, pick id, description)]}} for every player on the group's open,
    public slips (and the players the group tracks with /player)."""
    since = iso(now - timedelta(days=AUTOPILOT_DAYS))
    out: dict[str, dict] = {}
    rows = db().execute("SELECT * FROM picks WHERE guild_id = ? AND status = 'open' AND created_at >= ? "
                        "AND (hidden IS NULL OR hidden = 0) ORDER BY id DESC LIMIT 60", (gid, since)).fetchall()
    for p in rows:
        legs = get_legs(p["id"])
        texts = [x["text"] for x in legs if x["status"] == "open"] or ([] if legs else [p["description"]])
        paths = prop_paths_for(p)
        for text in texts:
            leg = prop_of(text)
            if not leg:
                continue
            for part in leg.get("combo") or [leg]:
                fams = {STATS[k][1] for k in part["stats"]}
                ok = [x for x in paths if FAMILY_OF_PATH.get(x) in fams]
                w = out.setdefault(part["player"], {"name": part.get("display") or part["player"].title(),
                                                    "paths": [], "slips": []})
                w["paths"] = list(dict.fromkeys(w["paths"] + ok))
                tag = (p["bettor_name"], p["id"], p["description"])
                if tag not in w["slips"]:
                    w["slips"].append(tag)
    for r in db().execute("SELECT name, sport FROM players WHERE guild_id = ? LIMIT 60", (gid,)).fetchall():
        key = norm_name(r["name"])
        paths = [x for x in leagues_for(r["sport"]) if x in PROP_PATHS] if r["sport"] else []
        w = out.setdefault(key, {"name": r["name"], "paths": [], "slips": []})
        w["paths"] = list(dict.fromkeys(w["paths"] + paths)) or list(PROP_PATHS)
    return out


async def news_status(watch: dict) -> dict[str, Optional[dict]]:
    """{player key: injury entry or None when he isn't on any report}. Players whose name fits more than one
    listed player are left out (no guessing)."""
    reports: dict[str, dict] = {}
    failed: set = set()
    for path in {x for w in watch.values() for x in w["paths"]}:
        reports[path] = await fetch_injuries(path)
        if path not in _injury_cache:          # a good fetch is always cached: this one failed
            failed.add(path)
    out: dict[str, Optional[dict]] = {}
    for key, w in watch.items():
        found = []
        for path in w["paths"]:
            for k, v in (reports.get(path) or {}).items():
                sc = name_score(key, k)
                if sc >= 2:
                    found.append((sc, dict(v, path=path)))
        if not found and failed.intersection(w["paths"]):
            continue                           # his report didn't load: no news either way
        if found:
            best = max(s for s, _ in found)
            top = {(v["name"], v.get("team") or ""): v for s, v in found if s == best}
            if any(v.get("ambiguous") for v in top.values()):
                top[("", "")] = {}                 # the report itself lists two players by this name
            out[key] = next(iter(top.values())) if len(top) == 1 else None
            if len(top) > 1:
                out.pop(key)
        else:
            out[key] = None
        if out.get(key) is None and "football/nfl" in w["paths"] and "sleeper_injury" in globals():
            try:
                sl = await sleeper_injury(key)
            except Exception:
                sl = None
            if sl:
                out[key] = sl
    return out


def news_slips_line(w: dict) -> str:
    bits = [f"{clip(who, 24)}'s {clip(desc, 30)} (`#{pid}`)" for who, pid, desc in w["slips"][:4]]
    more = len(w["slips"]) - 4
    return ("On: " + ", ".join(bits) + (f" and {more} more" if more > 0 else "")) if bits else "A player you track"


async def news_reboots(gid: int, now: datetime) -> list[tuple[str, str]]:
    """(key, line) for legs that just got voided because the player didn't play."""
    since = iso(now - timedelta(hours=36))
    rows = db().execute(
        """SELECT l.pick_id, l.idx, l.text, l.note, p.bettor_name, p.description, p.platform, p.hidden,
                  (SELECT COUNT(*) FROM legs l2 WHERE l2.pick_id = l.pick_id) AS n
           FROM legs l JOIN picks p ON p.id = l.pick_id
           WHERE p.guild_id = ? AND l.status = 'push' AND l.note LIKE '%didn''t play%'
             AND COALESCE(p.settled_at, p.created_at) >= ?""", (gid, since)).fetchall()
    out = []
    for r in rows:
        if r["hidden"]:
            continue
        dfs = is_dfs(r["platform"] or "")
        n = r["n"] or 1
        tail = (f" {clip(r['bettor_name'], 30)}'s {n}-pick drops to a {n - 1}-pick (`#{r['pick_id']}`)." if dfs and n > 2
                else f" That leg is voided on {clip(r['bettor_name'], 30)}'s {clip(r['description'], 40)} (`#{r['pick_id']}`).")
        out.append((f"dnp:{r['pick_id']}:{r['idx']}",
                    f"🔁 **Reboot:** {clip(r['note'], 120)}.{tail}"))
    return out


async def news_job(client, now: Optional[datetime] = None) -> None:
    """Every 10 minutes per server with an ask channel: post what changed on the injury reports and any reboots."""
    now = now or datetime.now(timezone.utc)
    c = news_db()
    for r in db().execute("SELECT guild_id, value FROM settings WHERE key = 'ask_channel' AND value IS NOT NULL").fetchall():
        gid = r["guild_id"]
        try:
            if not server_on(gid, "newsfeed"):
                continue
            last = get_setting(gid, "news_checked")
            if last and datetime.fromisoformat(last) > now - timedelta(minutes=NEWS_EVERY_MIN):
                continue
            set_setting(gid, "news_checked", iso(now))
            channel = client.get_channel(int(r["value"])) if str(r["value"]).isdigit() else None
            if channel is None:
                continue
            first = c.execute("SELECT 1 FROM news_seen WHERE guild_id = ? LIMIT 1", (gid,)).fetchone() is None
            watch = await news_watchlist(gid, now)
            status = await news_status(watch) if watch else {}
            updates: list[tuple[str, str]] = []
            for key, inj in status.items():
                w = watch[key]
                row = c.execute("SELECT status, detail FROM news_seen WHERE guild_id = ? AND key = ?",
                                (gid, f"inj:{key}")).fetchone()
                was = row["status"] if row else None
                now_st = inj["status"] if inj else None
                if (was or "").lower() == (now_st or "").lower():
                    continue                       # same status ("Out" vs "OUT" from the backup feed is no news)
                c.execute("INSERT OR REPLACE INTO news_seen (guild_id, key, status, detail, posted_at) VALUES (?,?,?,?,?)",
                          (gid, f"inj:{key}", now_st, (inj or {}).get("comment"), iso(now)))
                if inj:
                    head = (f"{news_icon(now_st)} **{clip(inj['name'], 60)}** ({clip(inj.get('team') or '', 40)}) is "
                            f"**{clip(now_st, 30)}**" + (f" (was {clip(was, 20)})" if was else ""))
                    body = (f"\n> {clip(inj['comment'], 220)}" if inj.get("comment") else "")
                    updates.append((key, f"{head}{body}\n-# {news_slips_line(w)}"))
                elif was and w["slips"]:
                    updates.append((key, f"✅ **{clip(w['name'], 60)}** is off the injury report (was {clip(was, 20)}).\n"
                                         f"-# {news_slips_line(w)}"))
            for key, line in await news_reboots(gid, now):
                if c.execute("SELECT 1 FROM news_seen WHERE guild_id = ? AND key = ?", (gid, key)).fetchone():
                    continue
                c.execute("INSERT INTO news_seen (guild_id, key, status, posted_at) VALUES (?,?,?,?)",
                          (gid, key, "posted", iso(now)))
                updates.append((key, line))
            c.commit()
            if not updates:
                continue
            if first:
                listed = [u for k, u in updates if not k.startswith("dnp:")]
                text = ("📰 **Injury watch is on.** I'll post here when anyone on the group's open slips shows up on "
                        "(or comes off) an injury report, and when a player doesn't play.\n\nOn the reports right now:\n"
                        + "\n".join(listed[:12]))
                for chunk in split_message(text):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())
                continue
            if len(updates) > NEWS_MAX_POSTS:
                text = "📰 **News roundup**\n\n" + "\n\n".join(u for _, u in updates)
                for chunk in split_message(text):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())
            else:
                for _, u in updates:
                    await channel.send(clip(u, 1990), allowed_mentions=discord.AllowedMentions.none())
        except Exception:
            log.warning("News feed failed for guild %s", gid, exc_info=True)
    # forget old reboot marks
    c.execute("DELETE FROM news_seen WHERE key LIKE 'dnp:%' AND posted_at < ?", (iso(now - timedelta(days=7)),))
    c.commit()


EXTRA_JOBS.append(("news_feed", news_job))
SERVER_TOGGLES.append(("newsfeed", "News feed in the ask channel", "optout"))
HELP_EXTRA.append(("💬 Ask channel", (
    "Admins: `/admin askchannel` picks a channel where **anything you type is a question for the bot** (no @mention), "
    "and screenshots get a breakdown instead of being logged. The bot also posts news there: players on the group's "
    "open slips landing on (or coming off) the injury report, and 🔁 reboots when a player doesn't play.")))


async def ask_channel_message(client, message) -> None:
    """A message in the ask channel: screenshots get a breakdown (never logged), words get an answer."""
    images = image_attachments(message)
    if images:
        await client.review_slip(message, message, images[0])
        return
    ref = message.reference.resolved if getattr(message, "reference", None) else None
    if isinstance(ref, discord.Message) and not ref.author.bot and not client.mentions_me(message):
        return                                   # people talking to each other in a reply
    words = text_slip_words(message)
    if len(words.strip()) < 4:
        return                                   # "lol", "ok", an emoji
    if text_route(words) == "status":
        await client.slip_status(message)
        return
    await client.handle_ask(message)


# ==========================================================================
# r29: more data providers. Official free feeds back up ESPN for live stats (NHL.com, MLB Stats API, Sleeper for
# the NFL) and fill in stats ESPN's box score doesn't carry (total bases, stolen bases...). Sleeper's injury
# statuses back up ESPN's NFL injury report in the news feed. No keys needed for any of them.
# ==========================================================================

NHL_WEB = "https://api-web.nhle.com/v1"
MLB_API = "https://statsapi.mlb.com/api/v1"
SLEEPER = "https://api.sleeper.app/v1"
HEALTH_NAMES.update({"api-web.nhle.com": "NHL.com", "statsapi.mlb.com": "MLB Stats API", "api.sleeper.app": "Sleeper"})
ALT_SOURCES = {"hockey/nhl": "NHL.com", "baseball/mlb": "MLB Stats API", "football/nfl": "Sleeper"}
_ALT_CACHE: dict = {}

async def _alt_get(url: str, params: dict, ttl: float) -> Optional[dict]:
    key = (url, tuple(sorted(params.items())))
    hit = _ALT_CACHE.get(key)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    try:
        data = await _get_json(url, params)
    except Exception:
        log.debug("Backup feed failed: %s", url, exc_info=True)
        data = None
    _ALT_CACHE[key] = (time.monotonic() + (ttl if data is not None else 120), data)
    if len(_ALT_CACHE) > 600:
        for k in list(_ALT_CACHE)[:300]:
            _ALT_CACHE.pop(k, None)
    return data


def _alt_live(ev: dict) -> bool:
    return ev.get("state") == "in"


def _alt_nick(t: dict) -> str:
    """'Celtics' from ESPN's short name (or the last word of the full name)."""
    return norm_team(t.get("short") or (t.get("name") or "").split(" ")[-1])


def _alt_pick(cands: list, ev: dict):
    """The candidate (start time or None, value) closest to ESPN's start; None when even the best is 6h+ off."""
    if not cands:
        return None
    t = event_time(ev)
    timed = [(abs((c - t).total_seconds()), v) for c, v in cands if c is not None and t is not None]
    if timed:
        gap, v = min(timed, key=lambda x: x[0])
        return v if gap <= 6 * 3600 else None
    return cands[0][1]


def _alt_when(text) -> Optional[datetime]:
    try:
        return datetime.fromisoformat(str(text).replace("Z", "+00:00")) if text else None
    except ValueError:
        return None


def _alt_days(ev: dict) -> list[str]:
    """The game's date in US Eastern time (the leagues' own calendars), and the day before, as YYYY-MM-DD."""
    t = event_time(ev)
    if t is None:
        return []
    et = t.astimezone(ZoneInfo("America/New_York")).date()
    return [et.isoformat(), (et - timedelta(days=1)).isoformat()]


# ---- NHL.com -------------------------------------------------------------------------------------------------

ALT_NHL_ABBR = {"NJ": "NJD", "TB": "TBL", "LA": "LAK", "SJ": "SJS", "UTAH": "UTA", "MON": "MTL", "WAS": "WSH"}


async def alt_nhl_box(ev: dict) -> Optional[dict]:
    away, home = lv_sides(ev)
    want = {_alt_nick(away), _alt_nick(home)}
    want_ab = {ALT_NHL_ABBR.get((t.get("abbr") or "").upper(), (t.get("abbr") or "").upper()) for t in (away, home)}
    gid = None
    for day in _alt_days(ev):
        data = await _alt_get(f"{NHL_WEB}/score/{day}", {}, 120 if _alt_live(ev) else 1800)
        cands = []
        for g in (data or {}).get("games") or []:
            if not isinstance(g, dict):
                continue
            names = {norm_team(((g.get(s) or {}).get("name") or {}).get("default") or "") for s in ("awayTeam", "homeTeam")}
            abbrs = {str((g.get(s) or {}).get("abbrev") or "").upper() for s in ("awayTeam", "homeTeam")}
            if want <= names or ("" not in want_ab and want_ab <= abbrs):
                cands.append((_alt_when(g.get("startTimeUTC")), g.get("id")))
        gid = _alt_pick(cands, ev)
        if gid:
            break
    if not gid:
        return None
    box = await _alt_get(f"{NHL_WEB}/gamecenter/{gid}/boxscore", {}, 60 if _alt_live(ev) else 6 * 3600)
    if not box:
        return None
    state = {"OFF": "post", "FINAL": "post", "LIVE": "in", "CRIT": "in"}.get(box.get("gameState"), "pre")
    players = []
    for side in ("awayTeam", "homeTeam"):
        grp = ((box.get("playerByGameStats") or {}).get(side)) or {}
        for pos in ("forwards", "defense", "goalies"):
            for p in grp.get(pos) or []:
                name = ((p.get("name") or {}).get("default")) or ""
                full = " ".join(x for x in ((p.get("firstName") or {}).get("default"), (p.get("lastName") or {}).get("default"))
                                if x) or name
                toi = str(p.get("toi") or "00:00")
                comps = {"g": p.get("goals"), "a": p.get("assists"), "sog": p.get("sog"), "hits_nhl": p.get("hits"),
                         "blocked": p.get("blockedShots")} if pos != "goalies" else {"saves": p.get("saves")}
                players.append({"name": full, "norm": norm_name(full), "dnp": toi in ("00:00", "0:00", ""),
                                "comps": {k: float(v) for k, v in comps.items() if isinstance(v, (int, float))}})
    return {"state": state, "players": players}


# ---- MLB Stats API -------------------------------------------------------------------------------------------

async def alt_mlb_box(ev: dict) -> Optional[dict]:
    away, home = lv_sides(ev)
    want = {norm_team(away.get("name") or ""), norm_team(home.get("name") or "")}
    pk, state = None, "pre"
    for day in _alt_days(ev):
        data = await _alt_get(f"{MLB_API}/schedule", {"sportId": 1, "date": day}, 120 if _alt_live(ev) else 1800)
        cands = []
        for d in (data or {}).get("dates") or []:
            for g in d.get("games") or []:
                t = g.get("teams") or {}
                names = {norm_team(((t.get(s) or {}).get("team") or {}).get("name") or "") for s in ("away", "home")}
                if want <= names and g.get("gamePk"):
                    cands.append((_alt_when(g.get("gameDate")), g))
        g = _alt_pick(cands, ev)           # a doubleheader lists both games: the one at ESPN's start time
        if g:
            pk = g.get("gamePk")
            st = ((g.get("status") or {}).get("abstractGameState") or "").lower()
            state = {"final": "post", "live": "in"}.get(st, "pre")
            break
    if not pk:
        return None
    box = await _alt_get(f"{MLB_API}/game/{pk}/boxscore", {}, 60 if state == "in" else 6 * 3600)
    if not box:
        return None
    players = []
    for side in ("away", "home"):
        for p in (((box.get("teams") or {}).get(side) or {}).get("players") or {}).values():
            name = (p.get("person") or {}).get("fullName") or ""
            bat = (p.get("stats") or {}).get("batting") or {}
            pit = (p.get("stats") or {}).get("pitching") or {}
            comps = {}
            # both the box-score names and the per-game ("c_") names the tracker uses for PrizePicks stats
            for cs, k in ((("h", "c_h"), "hits"), (("r", "c_r"), "runs"), (("rbi", "c_rbi"), "rbi"),
                          (("hr", "c_hr"), "homeRuns"), (("bb", "c_bb"), "baseOnBalls"), (("so_bat",), "strikeOuts"),
                          (("c_tb",), "totalBases"), (("c_sb",), "stolenBases"), (("c_2b",), "doubles"),
                          (("c_3b",), "triples"), (("c_hbp",), "hitByPitch")):
                if isinstance(bat.get(k), (int, float)):
                    for c in cs:
                        comps[c] = float(bat[k])
            for cs, k in ((("k", "c_pk"), "strikeOuts"), (("h_allowed",), "hits"), (("er", "c_er"), "earnedRuns"),
                          (("bb_allowed",), "baseOnBalls"), (("outs", "c_outs"), "outs"),
                          (("c_pitches",), "numberOfPitches")):
                if isinstance(pit.get(k), (int, float)):
                    for c in cs:
                        comps[c] = float(pit[k])
            if "c_pitches" not in comps and isinstance(pit.get("pitchesThrown"), (int, float)):
                comps["c_pitches"] = float(pit["pitchesThrown"])
            players.append({"name": name, "norm": norm_name(name), "dnp": not bat and not pit, "comps": comps})
    return {"state": state, "players": players}


# ---- Sleeper (NFL) -------------------------------------------------------------------------------------------

_SLEEPER_PLAYERS: dict = {"at": 0.0, "by_id": {}, "by_name": {}}


async def sleeper_players() -> dict:
    """{player id: {name, norm, team, pos, injury, body, notes}} from Sleeper's player list (fetched at most daily,
    as Sleeper asks)."""
    if _SLEEPER_PLAYERS["by_id"] and time.monotonic() - _SLEEPER_PLAYERS["at"] < 20 * 3600:
        return _SLEEPER_PLAYERS["by_id"]
    if _SLEEPER_PLAYERS["at"] and time.monotonic() - _SLEEPER_PLAYERS["at"] < 600 and not _SLEEPER_PLAYERS["by_id"]:
        return {}                                  # failed recently: don't hammer it
    _SLEEPER_PLAYERS["at"] = time.monotonic()
    try:
        raw = await _get_json(f"{SLEEPER}/players/nfl", {})
    except Exception:
        log.warning("Sleeper player list failed", exc_info=True)
        return _SLEEPER_PLAYERS["by_id"]
    by_id, by_name = {}, {}
    if not isinstance(raw, dict):
        log.warning("Sleeper player list wasn't readable")
        return _SLEEPER_PLAYERS["by_id"]
    for pid, p in raw.items():
        if not isinstance(p, dict) or not p.get("full_name") or p.get("position") in (None, "DEF"):
            continue
        rec = {"name": p["full_name"], "norm": norm_name(p["full_name"]), "team": (p.get("team") or "").upper(),
               "pos": p.get("position") or "", "injury": p.get("injury_status") or "",
               "body": p.get("injury_body_part") or "", "notes": p.get("injury_notes") or ""}
        by_id[str(pid)] = rec
        by_name.setdefault(rec["norm"], []).append(str(pid))
    _SLEEPER_PLAYERS.update(by_id=by_id, by_name=by_name)
    return by_id


SLEEPER_COMPS = {"pass_yds": "pass_yd", "pass_td": "pass_td", "pass_int": "pass_int", "pass_cmp": "pass_cmp",
                 "pass_att": "pass_att", "rush_yds": "rush_yd", "rush_att": "rush_att", "rush_td": "rush_td", "rec": "rec",
                 "rec_yds": "rec_yd", "rec_td": "rec_td", "targets": "rec_tgt", "long_rec": "rec_lng",
                 "long_rush": "rush_lng", "fum_lost": "fum_lost", "fg_made": "fgm", "sacks": "idp_sack",
                 "tackles": "idp_tkl", "def_int": "idp_int"}
SLEEPER_TEAM = {"WSH": "WAS", "JAC": "JAX", "LA": "LAR"}


async def alt_nfl_box(ev: dict) -> Optional[dict]:
    week, season = ev.get("week"), ev.get("season")
    if not week or not season:
        return None
    kind = {1: "pre", 2: "regular", 3: "post"}.get(ev.get("season_type") or 2, "regular")
    stats = await _alt_get(f"{SLEEPER}/stats/nfl/{kind}/{season}/{week}", {}, 120 if _alt_live(ev) else 3 * 3600)
    if not stats or not isinstance(stats, dict):
        return None
    people = await sleeper_players()
    teams = {SLEEPER_TEAM.get((t.get("abbr") or "").upper(), (t.get("abbr") or "").upper()) for t in ev.get("teams") or []}
    players = []
    for pid, s in stats.items():
        who = people.get(str(pid))
        if not who or not isinstance(s, dict) or (teams and who["team"] and who["team"] not in teams):
            continue
        comps = {c: float(s[k]) for c, k in SLEEPER_COMPS.items() if isinstance(s.get(k), (int, float))}
        if s.get("gp"):                       # he played: a stat Sleeper leaves out is a zero
            for c in ("pass_yds", "pass_td", "pass_int", "rush_yds", "rush_td", "rec", "rec_yds", "rec_td", "fum_lost"):
                comps.setdefault(c, 0.0)
        players.append({"name": who["name"], "norm": who["norm"], "dnp": False, "comps": comps})
    return {"state": ev.get("state") or "pre", "players": players}


# ---- the hook: ESPN first, the backup feed when ESPN comes up short -----------------------------------------

ALT_BOX = {"hockey/nhl": alt_nhl_box, "baseball/mlb": alt_mlb_box, "football/nfl": alt_nfl_box}


def alt_value(pl: dict, stat_key: str) -> Optional[tuple[float, str]]:
    _, _, parts, _ = STATS[stat_key]
    total, shown = 0.0, []
    for comp, w in parts:
        v = pl["comps"].get(comp)
        if v is None:
            return None
        total += v * w
        shown.append((comp, v))
    detail = "" if len(parts) == 1 or len(parts) > 6 else \
        " (" + ", ".join(f"{v:g} {COMP_SHORT.get(c, c)}" for c, v in shown) + ")"
    return round(total, 2), detail


async def alt_try(out: dict, leg: dict, path: str, ev: dict, cand: dict, stat_key: str) -> dict:
    """Fill in a prop from the league's own feed when ESPN's box score didn't have it."""
    fn = ALT_BOX.get(path)
    if fn is None or out.get("value") is not None or ev.get("state") == "pre":
        return out
    try:
        box = await fn(ev)
    except Exception:
        log.debug("Backup box score failed", exc_info=True)
        return out
    if not box or not box["players"]:
        return out
    target = norm_name(cand.get("name") or leg["player"])
    scored = [(name_score(target, p["norm"]), p) for p in box["players"]]
    best = max((s for s, _ in scored), default=0)
    top = [p for s, p in scored if s == best and s >= 2]
    if len(top) != 1:
        return out                             # nobody, or two players it could be: no guessing
    pl = top[0]
    if box["state"] in ("in", "post"):
        out["state"] = box["state"] if out["state"] != "post" else "post"
    src = ALT_SOURCES.get(path, "backup feed")
    if pl["dnp"]:
        if out["state"] == "post" and box["state"] == "post":
            out["result"], out["why"] = "push", f"{pl['name']} didn't play (per {src})"
        return out
    got = alt_value(pl, stat_key)
    if got is None:
        return out
    out["source"] = src
    return track_judge(out, leg, (got[0], got[1] + f" · {src}"), pl["name"])


# ---- injuries: Sleeper backs up ESPN's NFL report ----------------------------------------------------------

SLEEPER_INJURY = {"out": "Out", "ir": "Out", "pup": "Out", "sus": "Suspension", "doubtful": "Doubtful",
                  "questionable": "Questionable", "cov": "Out", "na": None}


async def sleeper_injury(player_norm: str) -> Optional[dict]:
    """An NFL player's injury status from Sleeper ({name, status, comment, team}), when it names one player."""
    await sleeper_players()
    ids = _SLEEPER_PLAYERS["by_name"].get(player_norm) or []
    if len(ids) != 1:
        return None
    p = _SLEEPER_PLAYERS["by_id"][ids[0]]
    st = SLEEPER_INJURY.get((p["injury"] or "").lower().strip(), p["injury"] or None)
    if not st:
        return None
    comment = " · ".join(x for x in (p["body"], p["notes"]) if x)
    return {"name": p["name"], "status": st, "comment": comment, "team": p["team"], "path": "football/nfl",
            "source": "Sleeper"}


def data_sources_line() -> str:
    """For /admin status: every feed the bot reads and how it's doing."""
    now = time.time()
    parts = []
    for host, label in HEALTH_NAMES.items():
        h = DATA_HEALTH.get(host)
        if not h:
            parts.append(f"⚪ {label}")
            continue
        bad = h.get("streak", 0) >= 3
        parts.append(f"{'🔴' if bad else '🟢'} {label}")
    return " · ".join(parts)


HELP_EXTRA.append(("📚 Data sources", (
    "Live stats come from ESPN, backed up by the leagues' own free feeds: NHL.com for hockey, the MLB Stats API for "
    "baseball and Sleeper for the NFL. When ESPN's box score is missing a player or a stat (like total bases), the "
    "bot checks those. NFL injury news also checks Sleeper. `/admin status` shows how each feed is doing.")))


